entries[168560] = { ["name"] = "Fetisch der vergoldeten Katakomben", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Anima von Leben und Tod'.\nGroße Macht:\nAnima des Todes\nSofort 2 min Abklingzeit Ihr nutzt Eure Lebenskraft, um Gegner zu verbrennen. Ihr fügt allen Gegnern in der Nähe 10% Eurer maximalen Gesundheit als Feuerschaden zu und werdet pro getroffenem Gegner um 10% Eurer maximalen Gesundheit geheilt, bis zu 50% Eurer maximalen Gesundheit.\nGeringe Macht:\nAnima des Lebens\nAzeritenergie strömt durch Eure Adern und erhöht Eure maximale Gesundheit alle 5 Sek. um 244 . Bis zu 10-mal stapelbar. Während Ihr über maximale Stapel verfügt, werdet Ihr alle 5 Sek. um 185 Gesundheit geheilt.\n\nGewährt Euch einen Stapel von 'Anima des Lebens', wenn Ihr einen Gegner besiegt, der Erfahrung oder Ehre gewährt.\n\nDieser Effekt endet, wenn Eure Gesundheit unter 35% fällt." }
entries[168566] = { ["name"] = "Nullkraftkühler", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Nullifikationsdynamo'.\nErfordert einen wohlwollenden Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nVerstärkte Nullbarriere\nSofort 2.25 min Abklingzeit Gewährt eine verstärkte Nullbarriere, die 10 Sek. lang [ 11391 * (1 + Vielseitigkeit)] Magieschaden absorbiert.\nGeringe Macht:\nNullbarriere\nGewährt alle 15 Sek. eine Nullbarriere. Diese absorbiert die nächsten [ 2268 * (1 + Vielseitigkeit)] Magieschaden, die Ihr innerhalb von 10 Sek. erleidet." }
entries[168568] = { ["name"] = "Nullkraftnullifizierer", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Nullifikationsdynamo'.\nErfordert einen respektvollen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Rostbolzenwiderstand, um diese Essenz freizuschalten.\nGroße Macht:\nVerstärkte Nullbarriere\nSofort 2.25 min Abklingzeit Gewährt eine verstärkte Nullbarriere, die 10 Sek. lang [ 11391 * (1 + Vielseitigkeit)] Magieschaden absorbiert, und entfernt sofort alle schädlichen Magie-, Fluch-, Gift- und Krankheitseffekte von Euch.\nGeringe Macht:\nNullbarriere\nGewährt alle 15 Sek. eine Nullbarriere. Diese absorbiert die nächsten [ 2268 * (1 + Vielseitigkeit)] Magieschaden, die Ihr innerhalb von 10 Sek. erleidet.\n\nWenn 'Nullbarriere' abläuft, implodiert sie und verursacht Schattenschaden in Höhe des insgesamt absorbierten Schadens, der auf alle Gegner in der Nähe aufgeteilt wird." }
entries[168569] = { ["name"] = "Nullkraftvisualisierer", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Nullifikationsdynamo'.\nGroße Macht:\nVerstärkte Nullbarriere\nSofort 2.25 min Abklingzeit Gewährt eine verstärkte Nullbarriere, die 10 Sek. lang [ 11391 * (1 + Vielseitigkeit)] Magieschaden absorbiert, und entfernt sofort alle schädlichen Magie-, Fluch-, Gift- und Krankheitseffekte von Euch.\nGeringe Macht:\nNullbarriere\nGewährt alle 15 Sek. eine Nullbarriere. Diese absorbiert die nächsten [ 2268 * (1 + Vielseitigkeit)] Magieschaden, die Ihr innerhalb von 10 Sek. erleidet.\n\nWenn 'Nullbarriere' abläuft, implodiert sie und verursacht Schattenschaden in Höhe des insgesamt absorbierten Schadens, der auf alle Gegner in der Nähe aufgeteilt wird." }
entries[168573] = { ["name"] = "Todesresistentes Blatt", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Unendlichkeit'.\nGroße Macht:\nBerührung des Ewigwährenden\nEuer nächster Tod wird verhindert. Stattdessen stellt Ihr 20% Eurer maximalen Gesundheit wieder her und erleidet 3 Sek. lang 85% weniger Schaden.\n\nDieser Effekt kann nur ein Mal alle 10 Min. auftreten.\nGeringe Macht:\nÜberlebenswille\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 30% länger an . Dieser Effekt kann nur ein Mal alle 1.5 Min. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n\"Gedeiht im Wind.\"" }
entries[168574] = { ["name"] = "Versteinerte lebende Rinde", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Unendlichkeit'.\nGroße Macht:\nBerührung des Ewigwährenden\nEuer nächster Tod wird verhindert. Stattdessen stellt Ihr 40% Eurer maximalen Gesundheit wieder her und erleidet 3 Sek. lang 85% weniger Schaden.\n\nDieser Effekt kann nur ein Mal alle 10 Min. auftreten.\nGeringe Macht:\nÜberlebenswille\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 30% länger an . Dieser Effekt kann nur ein Mal alle 60 Sek. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168575] = { ["name"] = "Ast der verjüngenden Ringe", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Unendlichkeit'.\nErlernt Rang 3 einer Essenz von den Rajani oder dem Abkommen von Uldum auf einem anderen Charakter, um diese Essenz freizuschalten.\nBenötigt einen respektvollen Ruf bei den Rajani. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nBerührung des Ewigwährenden\nEuer nächster Tod wird verhindert. Stattdessen stellt Ihr 40% Eurer maximalen Gesundheit wieder her und erleidet 3 Sek. lang 85% weniger Schaden.\n\nWenn Euer Tod verhindert wird, wird die Abklingzeit von ' Schildwall ' abgeschlossen.\n\nDieser Effekt kann nur ein Mal alle 10 Min. auftreten.\nGeringe Macht:\nÜberlebenswille\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 50% länger an . Dieser Effekt kann nur ein Mal alle 60 Sek. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168576] = { ["name"] = "Wurzeln der wunderbaren Wiederbelebung", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Unendlichkeit'.\nGroße Macht:\nBerührung des Ewigwährenden\nEuer nächster Tod wird verhindert. Stattdessen stellt Ihr 40% Eurer maximalen Gesundheit wieder her und erleidet 3 Sek. lang 85% weniger Schaden.\n\nWenn Euer Tod verhindert wird, wird die Abklingzeit von ' Schildwall ' abgeschlossen.\n\nDieser Effekt kann nur ein Mal alle 10 Min. auftreten.\nGeringe Macht:\nÜberlebenswille\nWenn Eure Gesundheit unter 35% fällt, erhaltet Ihr für 15 Sek. 55 Vermeidung und Euer nächster Einsatz von ' Aktive Mitigation ' hält 50% länger an . Dieser Effekt kann nur ein Mal alle 60 Sek. auftreten.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168577] = { ["name"] = "Magiegetränkte Perle", ["text"] = "Questgegenstand\n\"Energie flackert im Inneren.\"" }
entries[168578] = { ["name"] = "Sphäre der unterdrückten Kraft", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Sphäre der Unterdrückung'.\nGroße Macht:\nUnterdrückungsimpuls\nSofort 1 min Abklingzeit Entfesselt einen großen Impuls unterdrückender Energie, der 8 Sek. lang die Bewegungsgeschwindigkeit aller Gegner innerhalb von 15 Metern um 70% und ihr Angriffstempo um 25% verringert.\nGeringe Macht:\nSphäre der Unterdrückung\nUnbegrenzte Reichweite Wenn Euch ein Gegner im Nahkampf angreift, wird seine Bewegungsgeschwindigkeit um 30% verringert und Ihr erhaltet 5 Sek. lang 64 Tempo ." }
entries[168579] = { ["name"] = "Sphäre der ungezügelten Wut", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Sphäre der Unterdrückung'.\nErfordert den Erfolg \"Schlachtfeldraufbold\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nUnterdrückungsimpuls\nSofort 45 sek. Abklingzeit Entfesselt einen großen Impuls unterdrückender Energie, der 8 Sek. lang die Bewegungsgeschwindigkeit aller Gegner innerhalb von 15 Metern um 70% und ihr Angriffstempo um 25% verringert.\nGeringe Macht:\nSphäre der Unterdrückung\nUnbegrenzte Reichweite Wenn ein Gegner Euch im Nahkampf angreift, wird seine Bewegungsgeschwindigkeit um 30% verringert und Ihr erhaltet 7 Sek. lang 64 Tempo$?a294920[ und Geschwindigkeit].", ["unresolvedValues"] = true }
entries[168580] = { ["name"] = "Sphäre der geschröpften Mobilität", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Sphäre der Unterdrückung'.\nErfordert den Erfolg \"Schlachtfeldtaktiker\". (Kauf nicht möglich, wenn bereits bekannt)\nErlernt Rang 3 vom Blut des Feindes, des Kunstwerks der Zeit oder der Sphäre der Unterdrückung auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nUnterdrückungsimpuls\nSofort 45 sek. Abklingzeit Entfesselt einen großen Impuls unterdrückender Energie, der 8 Sek. lang die Bewegungsgeschwindigkeit aller Gegner innerhalb von 15 Metern um 70% und ihr Angriffstempo um 25% verringert.\n\nWenn Ihr einen Gegner trefft, erhaltet Ihr 8 Sek. lang 50% Bewegungsgeschwindigkeit.\nGeringe Macht:\nSphäre der Unterdrückung\nUnbegrenzte Reichweite Wenn ein Gegner Euch im Nahkampf angreift, wird seine Bewegungsgeschwindigkeit um 30% verringert und Ihr erhaltet 7 Sek. lang 64 Tempo und Geschwindigkeit." }
entries[168581] = { ["name"] = "Sphäre der lodernden Neutralisierung", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Sphäre der Unterdrückung'.\nGroße Macht:\nUnterdrückungsimpuls\nSofort 45 sek. Abklingzeit Entfesselt einen großen Impuls unterdrückender Energie, der 8 Sek. lang die Bewegungsgeschwindigkeit aller Gegner innerhalb von 15 Metern um 70% und ihr Angriffstempo um 25% verringert.\n\nWenn Ihr einen Gegner trefft, erhaltet Ihr 8 Sek. lang 50% Bewegungsgeschwindigkeit.\nGeringe Macht:\nSphäre der Unterdrückung\nUnbegrenzte Reichweite Wenn ein Gegner Euch im Nahkampf angreift, wird seine Bewegungsgeschwindigkeit um 30% verringert und Ihr erhaltet 7 Sek. lang 64 Tempo und Geschwindigkeit." }
