entries[168611] = { ["name"] = "Versteinerte kohlschwarze Schuppe", ["text"] = "Rang 1\nQuestgegenstand\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Schmelztiegel der Flammen'.\nGroße Macht:\nKonzentrierte Flamme\n40 Meter Reichweite Sofort 30 sek. Abklingzeit 1 Aufladung Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen.\n\nImmer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt.\nGeringe Macht:\nUralte Flamme\nCa. 3 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch ( 351 * 5) Feuerschaden im Verlauf von 10 Sek., Verbündete werden um ( 351 * 5) Gesundheit im Verlauf von 10 Sek. geheilt.\n\"Diese uralte Schuppe verkörpert die Erde und wurde in kohlschwarzem Feuer gehärtet.\"" }
entries[168612] = { ["name"] = "Traumglanzdrachenschuppe", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Schmelztiegel der Flammen'.\nGroße Macht:\nKonzentrierte Flamme\n40 Meter Reichweite Sofort 30 sek. Abklingzeit 1 Aufladung Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\nImmer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt.\nGeringe Macht:\nUralte Flamme\nCa. 1.25 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [Quellwert] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [Quellwert] Gesundheit im Verlauf von 10 Sek. geheilt.\n\"Aus der wiederhergestellten Schuppe strahlt das Leuchten des Smaragdgrünen Traums und die Essenz des grünen Drachenschwarms.\"", ["unresolvedValues"] = true }
entries[168613] = { ["name"] = "Gehärtete Schuppe der feuerroten Brutmutter", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Schmelztiegel der Flammen'.\nErlernt mit einem anderen Charakter 'Rang 3 - Schmelztiegel der Flammen', um diese Essenz freizuschalten.\nGroße Macht:\nKonzentrierte Flamme\n40 Meter Reichweite Sofort 30 sek. Abklingzeit 1 Aufladung Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\nImmer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt.\nMaximal 2 Aufladungen.\nGeringe Macht:\nUralte Flamme\nCa. 1.25 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [Quellwert] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [Quellwert] Gesundheit im Verlauf von 10 Sek. geheilt. Bis zu 3-mal stapelbar.\n\"Die Flammen der Lebensbinderin züngeln und tanzen über diese Schuppe, in der Lebensenergie sprudelt.\"", ["unresolvedValues"] = true }
entries[168614] = { ["name"] = "Aufgeladene Schuppe des Blauen Aspekts", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Schmelztiegel der Flammen'.\nGroße Macht:\nKonzentrierte Flamme\n40 Meter Reichweite Sofort 30 sek. Abklingzeit 1 Aufladung Beschießt Euer Ziel mit einer Kugel aus konzentrierten Flammen, die einem Gegner [ 824 * (1 + Vielseitigkeit)] Feuerschaden zufügen oder einen Verbündeten um [ 824 * (1 + Vielseitigkeit)] Gesundheit heilen. Die Flammen fügen dem Ziel danach zusätzlich 75% des Schadens im Verlauf von 6 Sek. zu oder heilen es um diesen Wert.\n\nImmer wenn Ihr 'Konzentrierte Flamme' einsetzt, erhöht sich der Schaden oder die Heilung um 100%. Dieser Bonus wird nach jedem dritten Einsatz zurückgesetzt.\nMaximal 2 Aufladungen.\nGeringe Macht:\nUralte Flamme\nCa. 1.25 Procs pro Minute Eure Zauber und Fähigkeiten haben eine Chance, das Ziel zu verbrennen oder zu kauterisieren. Gegner erleiden dadurch [Quellwert] Feuerschaden im Verlauf von 10 Sek., Verbündete werden um [Quellwert] Gesundheit im Verlauf von 10 Sek. geheilt. Bis zu 3-mal stapelbar.\n\"Blaue Magie knistert um die Schuppe und verkörpert den einst großen Aspekt.\"", ["unresolvedValues"] = true }
entries[168615] = { ["name"] = "Flüchtige Weltader", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Resonanz der Weltader'.\nGroße Macht:\nResonanz der Weltader\nSofort 1 min Abklingzeit Konzentriert Energie in das Herz von Azeroth und lässt 2 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 12 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\nErhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 8 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\nGeringe Macht:\nLebensblut\nAlle 18-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 12 Sek. lang bestehen bleibt.\n\nLebensblutsplitter\nDer Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 12 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\n\"Die Azerit anziehende Energie dieser Weltader ist förmlich spürbar und stellt für jeden, der damit umzugehen versteht, eine große Unterstützung dar.\"" }
entries[168616] = { ["name"] = "Starke Weltader", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Resonanz der Weltader'.\nGroße Macht:\nResonanz der Weltader\nSofort 1 min Abklingzeit Konzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\nErhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 8 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\nGeringe Macht:\nLebensblut\nAlle 18-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\nLebensblutsplitter\nDer Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 8 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\n\"Diese Weltader ist sehr robust und scheint das anliegende Azerit zu verstärken.\"" }
entries[168617] = { ["name"] = "Wogende Weltader", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Resonanz der Weltader'.\nErlernt mit einem anderen Charakter 'Rang 3 - Resonanz der Weltader', um diese Essenz freizuschalten.\nGroße Macht:\nResonanz der Weltader\nSofort 1 min Abklingzeit Konzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\nErhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 12 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\nGeringe Macht:\nLebensblut\nAlle 1-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\nLebensblutsplitter\nDer Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 12 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\n\"Diese Weltader weist eine viel schnellere innere Vibration auf und wird Azeritsplitter viel häufiger anziehen.\"" }
entries[168618] = { ["name"] = "Strahlende Weltader", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Resonanz der Weltader'.\nGroße Macht:\nResonanz der Weltader\nSofort 1 min Abklingzeit Konzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\nErhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 12 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\nGeringe Macht:\nLebensblut\nAlle 1-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\nLebensblutsplitter\nDer Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 12 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren.\n\"Die Strahlkraft und Intensität dieser Weltader ist Ehrfurcht gebietend.\"" }
entries[168619] = { ["name"] = "Wappenrock des Rostbolzenwiderstands", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nBenötigt Rostbolzenwiderstand\n- Ehrfürchtig\nVerkaufspreis:" }
entries[168620] = { ["name"] = "Konvexlinse der Fokussierungsiris", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Fokussierungsiris'.\nGroße Macht:\nFokussierter Azeritstrahl\nWirken in 2 sek. 1.5 min Abklingzeit Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 757 * 10) Feuerschaden zuzufügen.\nGeringe Macht:\nFokussierte Energie\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang 5 Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen. (500ms Abklingzeit)\n\"Azeritkristalle bilden sich auf dieser uralten Linse und verstärken die ihr innewohnende Fähigkeit, Magie zu formen und zu einem Feuerstrom zu bündeln.\"" }
entries[168621] = { ["name"] = "Vergrößernde Linse der Fokussierungsiris", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Fokussierungsiris'.\nGroße Macht:\nFokussierter Azeritstrahl\nWirken in 1.333 sek. 1.5 min Abklingzeit Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden zuzufügen.\nGeringe Macht:\nFokussierte Energie\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [Quellwert] Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.\n\"Azeritkristalle bilden sich auf dieser uralten Linse und verstärken die ihr innewohnende Fähigkeit, Magie zu formen und zu einem Feuerstrom zu bündeln.\"", ["unresolvedValues"] = true }
entries[168622] = { ["name"] = "Stabilisierende Linse der Fokussierungsiris", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Fokussierungsiris'.\nErlernt Rang 3 der Essenz der Fokussierungsiris, der Invokation der Lebensbinderin oder der Anima von Leben und Tod auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nFokussierter Azeritstrahl\nWirken in 1.333 sek. 1.5 min Abklingzeit Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden zuzufügen. Kann aus der Bewegung heraus eingesetzt werden.\nGeringe Macht:\nFokussierte Energie\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [Quellwert] Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.\n\nWenn Ihr keine Stapel von 'Fokussierte Energie' habt, gewährt Euer erster Einsatz eines Schadenszaubers oder einer Schadensfähigkeit Euch 3 Stapel.\n\"Azeritkristalle bilden sich auf dieser uralten Linse und verstärken die ihr innewohnende Fähigkeit, Magie zu formen und zu einem Feuerstrom zu bündeln.\"", ["unresolvedValues"] = true }
entries[168623] = { ["name"] = "Bikonkave Linse der Fokussierungsiris", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Essenz der Fokussierungsiris'.\nGroße Macht:\nFokussierter Azeritstrahl\nWirken in 1.333 sek. 1.5 min Abklingzeit Fokussiert überschüssige Azeritenergie in das Herz von Azeroth und setzt sie dann frei, um allen Gegnern vor Euch im Verlauf von 3 Sek. ( 891 * 10) Feuerschaden zuzufügen. Kann aus der Bewegung heraus eingesetzt werden.\nGeringe Macht:\nFokussierte Energie\nEure Schaden verursachenden Zauber und Fähigkeiten gewähren Euch 4 Sek. lang [Quellwert] Tempo. Dieser Effekt ist bis zu 10-mal stapelbar. Dieses Tempo geht verloren, sobald Ihr aufhört, Zauber oder Fähigkeiten gegen das ursprüngliche Ziel einzusetzen.\n\nWenn Ihr keine Stapel von 'Fokussierte Energie' habt, gewährt Euer erster Einsatz eines Schadenszaubers oder einer Schadensfähigkeit Euch 3 Stapel.\n\"Azeritkristalle bilden sich auf dieser uralten Linse und verstärken die ihr innewohnende Fähigkeit, Magie zu formen und zu einem Feuerstrom zu bündeln.\"", ["unresolvedValues"] = true }
entries[168624] = { ["name"] = "Vantusrune: Ewiger Palast", ["text"] = "Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Ewigen Palast ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:" }
entries[168625] = { ["name"] = "Vantusrunentechnik: Ewiger Palast", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Ewiger Palast herstellt.\nErschafft eine Vantusrune: Ewiger Palast.\nBenötigt Inschriftenkunde von Kul Tiras (155)\nVerkaufspreis:\nVantusrune: Ewiger Palast\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Ewigen Palast ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Tiefrote Tinte (20), Ultramarinblaue Tinte (10)" }
entries[168626] = { ["name"] = "Vantusrunentechnik: Ewiger Palast", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Ewiger Palast effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Ewiger Palast.\nBenötigt Inschriftenkunde von Kul Tiras (165)\nVerkaufspreis:\nVantusrune: Ewiger Palast\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Ewigen Palast ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Tiefrote Tinte (18), Ultramarinblaue Tinte (9)" }
entries[168627] = { ["name"] = "Vantusrunentechnik: Ewiger Palast", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Ewiger Palast effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Vantusrune: Ewiger Palast.\nBenötigt Inschriftenkunde von Kul Tiras (175)\nVerkaufspreis:\nVantusrune: Ewiger Palast\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Ewigen Palast ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Tiefrote Tinte (15), Ultramarinblaue Tinte (7)" }
