entries[168654] = { ["name"] = "Großes Fläschchen des Tiefensogs", ["text"] = "Benutzen: Erhöht die Stärke 1 Stunde lang um 108 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[168655] = { ["name"] = "Großes mystisches Fläschchen", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Gildenfläschchen (1)\nBenutzen: Gewährt den Effekt eines Fläschchens basierend auf Eurer Klasse und Euren Talenten. Hält 1 Stunde lang und über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[168656] = { ["name"] = "Großer mystischer Kessel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:" }
entries[168657] = { ["name"] = "Freund-Feind-Identifikator", ["text"] = "Blaue Lochkarte\nWird beim Aufheben gebunden\nAnlegen: Spürt mechanische Kreaturen in der Nähe auf und zeigt sie auf der Minikarte an.\nVerkaufspreis:" }
entries[168658] = { ["name"] = "Neptulische Muschel", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Festes, köstliches Fleisch mit leichtem Salzgehalt und süßer Note im Abgang. Schwer zu bekommen, ist aber die Mühe definitiv wert.\"" }
entries[168659] = { ["name"] = "Versteckte Brustrüstung", ["text"] = "Kosmetisch\nBrust Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[168660] = { ["name"] = "Bauplan: Blingtron 7000", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines Blingtron 7000.\nStellt Blingtron 7000 her.\nBenötigt Ingenieurskunst von Kul Tiras (175)\nBenötigt Rostbolzenwiderstand\n- Ehrfürchtig\nVerkaufspreis:\nBlingtron 7000\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt den verbesserten Blingtron 7000 zusammen, einen wilden, aber großzügigen Roboter. Einerseits lässt er Spielercharakteren einmal am Tag kleine Präsente zukommen, anderseits bekämpft er andere Blingtron-Einheiten bis zum Tode. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Platinerz (5), Sturmsilbererz (10), Bernsteinflamme (3), Laribol (3), Isoliertes Kabel (25)" }
entries[168662] = { ["name"] = "Tiefrote Pigmente", ["text"] = "Handwerksmaterial\n\"Wird häufig beim Mahlen von Pflanzen Nazjatars gefunden.\"\nVerkaufspreis:" }
entries[168663] = { ["name"] = "Tiefrote Tinte", ["text"] = "Handwerksmaterial\nVerkaufspreis:" }
entries[168664] = { ["name"] = "Versteckte Stiefel", ["text"] = "Kosmetisch\nFüße Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[168665] = { ["name"] = "Versteckte Armschienen", ["text"] = "Kosmetisch\nHandgelenk Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
