entries[168667] = { ["name"] = "Blingtron 7000", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt den verbesserten Blingtron 7000 zusammen, einen wilden, aber großzügigen Roboter. Einerseits lässt er Spielercharakteren einmal am Tag kleine Präsente zukommen, anderseits bekämpft er andere Blingtron-Einheiten bis zum Tode. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (1)" }
entries[168671] = { ["name"] = "Elektromagnetische Widerstände", ["text"] = "Blaue Lochkarte\nWird beim Aufheben gebunden\nAnlegen: Verringert die Auswirkungen von erzwungenen Bewegungseffekten.\nVerkaufspreis:" }
entries[168672] = { ["name"] = "Tiefentaucher", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schwimmt wie eine Kelfinne. (15 Sek. Abklingzeit)" }
entries[168673] = { ["name"] = "Schlüssel zum silbernen Monorad", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Lehrt Euch, wie man ein silbernes Monorad beschwört.\"" }
entries[168674] = { ["name"] = "Abyssischer Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 10 Vielseitigkeit\n\nPrismatischer Sockel\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 27 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Kul Tiras\n(165)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
