entries[168807] = { ["name"] = "Wurmlochgenerator: Kul Tiras", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Teleportiert den Spielercharakter an einen zufälligen Ort in Kul Tiras. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (1)\n\"Der Benutzer ist für die letztendlichen Teleportationszielorte allein verantwortlich und nicht berechtigt, rechtliche Schritte gegen den Hersteller dieses Geräts einzuleiten.\"\nVerkaufspreis:" }
entries[168808] = { ["name"] = "Wurmlochgenerator: Zandalar", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Teleportiert den Spielercharakter an einen zufälligen Ort in Zandalar. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (1)\n\"Der Benutzer ist für die letztendlichen Teleportationszielorte allein verantwortlich und nicht berechtigt, rechtliche Schritte gegen den Hersteller dieses Geräts einzuleiten.\"\nVerkaufspreis:" }
