entries[168811] = { ["name"] = "Zauberstab der Absorption", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Absorbiert die verbleibende Essenz eines anvisierten Ogers. Funktioniert nicht bei lebendigen Zielen." }
entries[168812] = { ["name"] = "Luftauffrischer", ["text"] = "\"Duftet nach Narzissen und Gold.\"\nVerkaufspreis:" }
entries[168813] = { ["name"] = "Robospeicheraufzeichner", ["text"] = "Questgegenstand\nBenutzen: Durchsucht die Datenbanken kürzlich ausrangierter Aufziehgiganten innerhalb von 10 Metern. (4 Sek. Abklingzeit)\n\"Durchsucht die Speicherbänke von Roboterkreaturen.\"" }
entries[168814] = { ["name"] = "Belebtes Blut der Dezimierten", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Blut des Feindes'.\nGroße Macht:\nBlut des Feindes\nSofort 1.5 min Abklingzeit Das Herz von Azeroth fügt Gegnern innerhalb von 12 Metern durch eine heftige Explosion 1739 Schattenschaden zu. Ihr erhaltet 10 Sek. lang 25% zusätzliche kritische Trefferchance gegen die Ziele und Euer kritischer Trefferschaden wird 5 Sek. lang um 25% erhöht.\nGeringe Macht:\nBlutgetränkt\nEure kritischen Treffer mit Zaubern und Fähigkeiten gewähren Euch einen Stapel von 'Blutgetränkt'. Jeder Stapel von 'Blutgetränkt' erhöht den kritischen Trefferwert um 2 . Bei 40 Stapeln erhaltet Ihr 8 Sek. lang 125 Tempo.\n\nEs besteht eine Chance von 25%, dass 'Blutgetränkt' nur 30 Stapel verbraucht." }
entries[168815] = { ["name"] = "Kelpbeerenfass", ["text"] = "Questgegenstand\nEinzigartig" }
entries[168816] = { ["name"] = "Pulsierendes Sternenherz", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Geist der Bewahrung'.\nGroße Macht:\nGeist der Bewahrung\n40 Meter Reichweite Kanalisiert (Wirken in 3 sek.) 1 min Abklingzeit Kanalisiert einen Energiestrahl auf einen Verbündeten und heilt ihn im Verlauf von 3 Sek. um [( 1452 * (5) + 1452 ) * (1 + Vielseitigkeit)] Gesundheit. Bis zu 6 andere Verbündete im Strahl werden alle 0.6 Sek. um [ 145 * (1 + Vielseitigkeit)] Gesundheit geheilt.\n\nImmer wenn 'Geist der Bewahrung' das Primärziel heilt, erhaltet Ihr einen Stapel von 'Ergebener Geist'.\nGeringe Macht:\nErgebener Geist\nErhaltet alle 5 Sek. 'Ergebener Geist, wodurch Euer nächster Einsatz von ' Schnellheilung ' um zusätzlich 153 Gesundheit heilt. Bis zu 5-mal stapelbar.\n\nJeder verbrauchte Stapel von 'Ergebener Geist' erhöht die kritische Trefferchance Eures nächsten Einsatzes von ' Schnellheilung ' innerhalb von 15 Sek. um 20%.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168817] = { ["name"] = "Entzugskristall", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entzieht einem Leylinienakkumulator in der Nähe Magie." }
entries[168818] = { ["name"] = "Sivaras Schlängelklinge", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n5 - 9 Schaden Geschwindigkeit 1.80\n(3.9 Schaden pro Sekunde)\n+3 Beweglichkeit\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
entries[168821] = { ["name"] = "Notfallraketenhühnchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Nützlich, um Stabilisatorschaden durch plötzliche, gravitationsbedingte Einschläge zu vermeiden. Festhalten! (3 Min Abklingzeit)" }
entries[168822] = { ["name"] = "Dünnflüssiges Gelée", ["text"] = "Benötigt eine Allianz-Rasse\n\"Wässrig und blass. Macht heranwachsende Bienen ein bisschen glücklich.\"\nVerkaufspreis:" }
entries[168823] = { ["name"] = "Rostiger Mechanokrabbler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Motorwarnleuchte leuchtet immer. Ihr solltet Euch erst Sorgen machen, wenn sie ausgeht.\"\nBeute von:\nMechagon" }
entries[168824] = { ["name"] = "Meeressimulator", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Taucht ein in die Geräusche des Ozeans. (1 Min Abklingzeit)\n\"Gönnt Euch einen Moment des Friedens, wo Ihr auch seid. Genießt die beruhigende Geräuschkulisse der Meeresküste.\"" }
entries[168825] = { ["name"] = "Reichhaltiges Gelée", ["text"] = "Benötigt eine Allianz-Rasse\n\"Dickflüssig und von goldener Farbe. Macht heranwachsende Bienen glücklich.\"\nVerkaufspreis:" }
entries[168826] = { ["name"] = "Friedensbewahrer von Mechagon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Bewahrt den Frieden, indem es einen auf ewig befriedet.\"\nBeute von:\nFliegende Unterdrückungseinheit JK-8\nZone:\nOperation: Mechagon (Mythisch)" }
entries[168827] = { ["name"] = "Schrottgeschmiedete Mechaspinne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ihr habt es selbst gebaut. Seid ruhig stolz darauf. Und nehmt Krawall und Abgas ganz einfach still in Kauf.\"\nQuest:\nNoch heute losfahren\nZone:\nMechagon" }
entries[168828] = { ["name"] = "Gelée Royale", ["text"] = "Benötigt eine Allianz-Rasse\n\"Einer Königin würdig. Macht heranwachsende Bienen sehr glücklich.\"\nVerkaufspreis:" }
entries[168829] = { ["name"] = "Rostbolzenresistor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Rostbolzenwiderstand\n- Ehrfürchtig\n\n\"In den Sitz wurde in grober Schrift \"W I D E R S T A N D\" geritzt. Das und noch ein paar profanere Dinge.\"\nVerkäufer:\nGestohlener königlicher Händlerbot\nZone:\nMechagon\nFraktion:\nRostbolzenwiderstand - Ehrfürchtig\nKosten:" }
entries[168830] = { ["name"] = "Lufteinheit R-21/X", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"König Mechagons private Lufteinheit samt einsatzbereiter Sprengkanone und Fußwärmern.\"\nBeute von:\nKönig Mechagon" }
entries[168832] = { ["name"] = "Galvanischer Oszillator", ["text"] = "Mechagontüfteleien\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein essentieller Bestandteil der fortgeschrittensten Verstärkungen.\"\nVerkaufspreis:" }
entries[168833] = { ["name"] = "Experimentelles Abenteureraccessoire", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Erschafft einen mächtigen Ring oder ein mächtiges Schmuckstück für Eure Spezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
