entries[168837] = { ["name"] = "Tiefengeschmiedete Aegis", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Aegis der Tiefe'.\nErfordert einen freundlichen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen freundlichen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nAegis der Tiefe\nSofort 1.5 min Abklingzeit Die Elemente schützen Euch und verringern 15 Sek. lang Euren durch jeden Angriff erlittenen Schaden um 395 .\nGeringe Macht:\nStandhalten\nIhr erhaltet 13 Vielseitigkeit für jeden Gegner innerhalb von 10 Metern, bis zu maximal ( 13 * 10) Vielseitigkeit." }
entries[168838] = { ["name"] = "Robustes Bollwerk der Tiefen", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Aegis der Tiefe'.\nErfordert einen wohlwollenden Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen wohlwollenden Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nAegis der Tiefe\nSofort 1.133 min Abklingzeit Die Elemente schützen Euch und verringern 15 Sek. lang Euren durch jeden Angriff erlittenen Schaden um 395 .\nGeringe Macht:\nStandhalten\nIhr erhaltet 13 Vielseitigkeit für jeden Gegner innerhalb von 10 Metern [bis zu maximal ( 13 * 10) Vielseitigkeit]. Bei unter 35% Gesundheit wird die Vielseitigkeit verdoppelt." }
entries[168839] = { ["name"] = "Regenerierende Barriere der Tiefen", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Aegis der Tiefe'.\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Ruf in Nazjatar, um diese Essenz freizuschalten.\nErfordert einen respektvollen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen respektvollen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nAegis der Tiefe\nSofort 1.133 min Abklingzeit Die Elemente schützen Euch und verringern 15 Sek. lang Euren durch jeden Angriff erlittenen Schaden um 395 . Wenn 'Aegis der Tiefe' abläuft, erhaltet Ihr 6 Sek. lang 27 Vermeidung.\nGeringe Macht:\nStandhalten\nIhr erhaltet 13 Vielseitigkeit für jeden Gegner innerhalb von 10 Metern, bis zu maximal ( 13 * 10) Vielseitigkeit. Bei unter 35% Gesundheit wird die Vielseitigkeit verdoppelt.\n\nHeilt Euch für jeden Stapel von 'Standhalten', der auf Euch wirkt, alle 4 Sek. um 208 Gesundheit." }
entries[168840] = { ["name"] = "Prunkvolle Bastion der Tiefen", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Aegis der Tiefe'.\nGroße Macht:\nAegis der Tiefe\nSofort 1.133 min Abklingzeit Die Elemente schützen Euch und verringern 15 Sek. lang Euren durch jeden Angriff erlittenen Schaden um 395 . Wenn 'Aegis der Tiefe' abläuft, erhaltet Ihr 6 Sek. lang 27 Vermeidung.\nGeringe Macht:\nStandhalten\nIhr erhaltet 13 Vielseitigkeit für jeden Gegner innerhalb von 10 Metern, bis zu maximal ( 13 * 10) Vielseitigkeit. Bei unter 35% Gesundheit wird die Vielseitigkeit verdoppelt.\n\nHeilt Euch für jeden Stapel von 'Standhalten', der auf Euch wirkt, alle 4 Sek. um 208 Gesundheit." }
entries[168841] = { ["name"] = "Schriftrolle der Shirakess", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Finstere Beschwörungen winden sich über die Schriftrolle.\"" }
entries[168842] = { ["name"] = "Mechaperfektionsmotor", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nGroße Macht:\nVision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 25% der Grunddauer zu aktivieren .\nGeringe Macht:\nStreben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% .\n\"Der Motor wurde aus einem uralten Titanengerät weiterentwickelt und ist ein Triumph gnomischer Erfindungsgabe. Er ermöglicht mechanischen Wesen, Höchstleistungen zu erreichen.\"" }
entries[168843] = { ["name"] = "Perfekt eingestelltes Differential", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nGroße Macht:\nVision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 35% der Grunddauer zu aktivieren .\nGeringe Macht:\nStreben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]%.\n\nDas Aktivieren von ' ' heilt Euch sofort um 5% der maximalen Gesundheit." }
entries[168844] = { ["name"] = "Leistungsperfektionsgetriebe", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nErlernt mit einem anderen Charakter 'Rang 3 - Vision der Perfektion', um diese Essenz freizuschalten.\nGroße Macht:\nVision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 35% der Grunddauer zu aktivieren .\n\nWenn 'Vision der Perfektion' aktiviert wird, erhaltet Ihr und bis zu 2 Verbündete in der Nähe 10 Sek. lang 24 Tempo.\nGeringe Macht:\nStreben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% und erhöht Eure Vielseitigkeit um 18 .\n\nDas Aktivieren von ' ' heilt Euch sofort um 5% der maximalen Gesundheit." }
entries[168845] = { ["name"] = "Mechaperfektionsturbo", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vision der Perfektion'.\nGroße Macht:\nVision der Perfektion\nEure Zauber und Fähigkeiten haben eine Chance, ' ' für 35% der Grunddauer zu aktivieren .\n\nWenn 'Vision der Perfektion' aktiviert wird, erhaltet Ihr und bis zu 2 Verbündete in der Nähe 10 Sek. lang 24 Tempo.\nGeringe Macht:\nStreben nach Perfektion\nVerringert die Abklingzeit von ' ' um [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% und erhöht Eure Vielseitigkeit um 18 .\n\nDas Aktivieren von ' ' heilt Euch sofort um 5% der maximalen Gesundheit.\n\"Dieser Turbo verbessert den Mechaperfektionsmotor und hat das Potenzial, gewaltige Mengen an Titanenenergie auf einen Schlag freizusetzen.\"" }
entries[168846] = { ["name"] = "Perle der Klarträume", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Erinnerung an den Klartraum'.\nGroße Macht:\nErinnerung an den Klartraum\nSofort 2 min Abklingzeit Macht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Hält 12 Sek. lang an.\nGeringe Macht:\nKlarträume\nEure Zauber und Fähigkeiten haben eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten und Euch um [ 764 * (1 + Vielseitigkeit)] Gesundheit zu heilen ." }
entries[168847] = { ["name"] = "Perle manifestierter Ambitionen", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Erinnerung an den Klartraum'.\nErfordert den Erfolg \"Reise durch die Tiefen\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nErinnerung an den Klartraum\nSofort 2 min Abklingzeit Macht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Hält 15 Sek. lang an.\nGeringe Macht:\nKlarträume\nEure Zauber und Fähigkeiten haben eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten und Euch um [ 764 * 1.5 * (1 + Vielseitigkeit)] Gesundheit zu heilen ." }
entries[168848] = { ["name"] = "Perle einleuchtender Absichten", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Erinnerung an den Klartraum'.\nErlernt mit einem anderen Charakter 'Rang 3 - Erinnerung an den Klartraum', um diese Essenz freizuschalten.\nErfordert den Erfolg \"Nautische Kampfausbildung\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nErinnerung an den Klartraum\nSofort 2 min Abklingzeit Macht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Zusätzlich erhaltet Ihr 66 Lebensraub. Hält 15 Sek. lang an.\nGeringe Macht:\nKlarträume\nEure Zauber und Fähigkeiten haben [eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten], Euch um [ 764 * (1.5) * (1 + Vielseitigkeit)] Gesundheit zu heilen und Eure Vielseitigkeit 8 Sek. lang um 74 zu erhöhen." }
entries[168849] = { ["name"] = "Perle illustrer Pläne", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Erinnerung an den Klartraum'.\nGroße Macht:\nErinnerung an den Klartraum\nSofort 2 min Abklingzeit Macht Euren Geist frei und stimmt Euch auf das Herz von Azeroth ein. Dadurch erzeugt Ihr 100% mehr . Zusätzlich erhaltet Ihr 66 Lebensraub. Hält 15 Sek. lang an.\nGeringe Macht:\nKlarträume\nEure Zauber und Fähigkeiten haben [eine Chance, in Höhe von 50% der verbrauchten Menge zu erstatten], Euch um [ 764 * (1.5) * (1 + Vielseitigkeit)] Gesundheit zu heilen und Eure Vielseitigkeit 8 Sek. lang um 74 zu erhöhen." }
entries[168850] = { ["name"] = "Zeitverlorenes Schlachtfeldandenken", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Raumwelle'.\nGroße Macht:\nRaumwelle\n25 Meter Reichweite Sofort 1 min Abklingzeit Erzeugt am Zielort ein Azeritleuchtfeuer. Nach 4 Sek. versetzt Euch das Herz von Azeroth zu diesem Leuchtfeuer und fügt allen Gegnern in der Nähe 1451 Feuerschaden zu.\nGeringe Macht:\nRealitätsverschiebung\nWenn Ihr Euch innerhalb von 4 Sek. um mehr als 25 Meter bewegt, erhaltet Ihr 15 Sek. lang 47 Primärwert .\n\nDieser Effekt kann nur ein Mal alle 30 Sek. auftreten.\n\"Die Erinnerungen an die Vergangenheit bergen eine tiefsitzende Kraft, die uns zu Momenten von großer Wichtigkeit zurückversetzt.\"" }
entries[168851] = { ["name"] = "Robustes Schlachtfeldandenken", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Raumwelle'.\nErfordert den Erfolg \"Krieg an zwei Fronten\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nRaumwelle\n25 Meter Reichweite Sofort 1 min Abklingzeit Erzeugt am Zielort ein Azeritleuchtfeuer. Nach 2 Sek. versetzt Euch das Herz von Azeroth zu diesem Leuchtfeuer und fügt allen Gegnern in der Nähe 1451 Feuerschaden zu.\nGeringe Macht:\nRealitätsverschiebung\nWenn Ihr Euch innerhalb von 4 Sek. um mehr als 25 Meter bewegt, erhaltet Ihr 20 Sek. lang 47 Primärwert .\n\nDieser Effekt kann nur ein Mal alle 30 Sek. auftreten." }
entries[168852] = { ["name"] = "Bruchfestes Schlachtfeldandenken", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Raumwelle'.\nErlernt mit einem anderen Charakter 'Rang 3 - Raumwelle', um diese Essenz freizuschalten.\nIhr habt nicht genug Auszeichnungen des Rufs zu den Waffen, um diesen Gegenstand zu kaufen.\nGroße Macht:\nRaumwelle\n25 Meter Reichweite Sofort 1 min Abklingzeit Erzeugt am Zielort ein Azeritleuchtfeuer. Nach 2 Sek. versetzt Euch das Herz von Azeroth zu diesem Leuchtfeuer und fügt allen Gegnern in der Nähe 1451 Feuerschaden zu.\n\nNach der Versetzung erleidet Ihr 10 Sek. lang 10% weniger Schaden.\nGeringe Macht:\nRealitätsverschiebung\nEure Bewegungsgeschwindigkeit wird um 5% erhöht, und wenn Ihr Euch innerhalb von 4 Sek. um mehr als 25 Meter bewegt, erhaltet Ihr 20 Sek. lang 47 Primärwert .\n\nDieser Effekt kann nur ein Mal alle 30 Sek. auftreten." }
entries[168853] = { ["name"] = "Glitzerndes Schlachtfeldandenken", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Raumwelle'.\nGroße Macht:\nRaumwelle\n25 Meter Reichweite Sofort 1 min Abklingzeit Erzeugt am Zielort ein Azeritleuchtfeuer. Nach 2 Sek. versetzt Euch das Herz von Azeroth zu diesem Leuchtfeuer und fügt allen Gegnern in der Nähe 1451 Feuerschaden zu.\n\nNach der Versetzung erleidet Ihr 10 Sek. lang 10% weniger Schaden.\nGeringe Macht:\nRealitätsverschiebung\nEure Bewegungsgeschwindigkeit wird um 5% erhöht, und wenn Ihr Euch innerhalb von 4 Sek. um mehr als 25 Meter bewegt, erhaltet Ihr 20 Sek. lang 47 Primärwert .\n\nDieser Effekt kann nur ein Mal alle 30 Sek. auftreten." }
entries[168854] = { ["name"] = "Belebtes Elementarherz", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Kondensierte Lebenskraft'.\nGroße Macht:\nWächter von Azeroth\nSofort 3 min Abklingzeit Beschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit)] Feuerschaden verursachen.\nGeringe Macht:\nKondensierte Lebenskraft\nCa. 2 Procs pro Minute Eure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit)] Feuerschaden zufügt.\n\"Auch die ehrfurchtgebietendsten Elementarlords sind einfachen steinernen Herzen entsprungen.\"" }
entries[168855] = { ["name"] = "Pulsierendes Elementarherz", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Kondensierte Lebenskraft'.\nGroße Macht:\nWächter von Azeroth\nSofort 3 min Abklingzeit Beschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden verursachen. Der Wächter verschießt alle 8 Sek. eine Salve aus Azeritstacheln auf sein Ziel, die allen Gegnern in der Nähe 670 Feuerschaden zufügen.\nGeringe Macht:\nKondensierte Lebenskraft\nCa. 2 Procs pro Minute Eure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden zufügt.\n\"Auch die ehrfurchtgebietendsten Elementarlords sind einfachen steinernen Herzen entsprungen.\"" }
entries[168856] = { ["name"] = "Resonierendes Elementarherz", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Kondensierte Lebenskraft'.\nErlernt Rang 3 der Kondensierten Lebenskraft, der Vitalitätsverbindung oder von Azeroths unsterblichem Geschenk auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nWächter von Azeroth\nSofort 3 min Abklingzeit Beschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden verursachen. Der Wächter verschießt alle 8 Sek. eine Salve aus Azeritstacheln auf sein Ziel, die allen Gegnern in der Nähe 670 Feuerschaden zufügen.\n\nJedes Mal, wenn der Wächter von Azeroth einen Zauber wirkt, erhaltet Ihr 2% Tempo (bis zu 5 - mal stapelbar). Dieser Effekt endet, wenn der Wächter von Azeroth verschwindet.\nGeringe Macht:\nKondensierte Lebenskraft\nCa. 2 Procs pro Minute Eure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden zufügt.\n\nWenn ein Azeritstachel Schaden verursacht, wird sämtlicher Schaden, den Ihr diesem Ziel zufügt, 6 Sek. lang um 3% erhöht.\n\"Auch die ehrfurchtgebietendsten Elementarlords sind einfachen steinernen Herzen entsprungen.\"" }
entries[168857] = { ["name"] = "Funkelndes Elementarherz", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Kondensierte Lebenskraft'.\nGroße Macht:\nWächter von Azeroth\nSofort 3 min Abklingzeit Beschwört einen Wächter von Azeroth, der Euch 30 Sek. lang im Kampf beisteht und Euer Ziel alle 2.5 Sek. mit Azeritstacheln aufspießt, die [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden verursachen. Der Wächter verschießt alle 8 Sek. eine Salve aus Azeritstacheln auf sein Ziel, die allen Gegnern in der Nähe 670 Feuerschaden zufügen.\n\nJedes Mal, wenn der Wächter von Azeroth einen Zauber wirkt, erhaltet Ihr 2% Tempo (bis zu 5 - mal stapelbar). Dieser Effekt endet, wenn der Wächter von Azeroth verschwindet.\nGeringe Macht:\nKondensierte Lebenskraft\nCa. 2 Procs pro Minute Eure Zauber und Fähigkeiten haben eine hohe Chance, das Ziel mit einem Azeritstachel aufzuspießen, der ihm [ 660 * (1 + Vielseitigkeit) * (1.25)] Feuerschaden zufügt.\n\nWenn ein Azeritstachel Schaden verursacht, wird sämtlicher Schaden, den Ihr diesem Ziel zufügt, 6 Sek. lang um 3% erhöht.\n\"Auch die ehrfurchtgebietendsten Elementarlords sind einfachen steinernen Herzen entsprungen.\"" }
entries[168858] = { ["name"] = "Titanenreinigungsprotokolle", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Reinigungsprotokoll'.\nErfordert einen freundlichen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nLäuternde Druckwelle\n40 Meter Reichweite Sofort 1 min Abklingzeit Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht.\n\nVom Strahl getroffene Entartungen werden für 3 Sek. betäubt.\nGeringe Macht:\nReinigungsprotokoll\nCa. 2 Procs pro Minute MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die jedem Gegner innerhalb von 8 Metern [ 563 * (1 + Vielseitigkeit)] Feuerschaden zufügt .\n\n'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu.\n\"Die Titanen haben Protokolle für die diversen Verderbnisse erstellt, die Azeroth befallen könnten.\"" }
entries[168859] = { ["name"] = "Gezielte Reinigungsprotokolle", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Reinigungsprotokoll'.\nErfordert einen wohlwollenden Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nLäuternde Druckwelle\n40 Meter Reichweite Sofort 1 min Abklingzeit Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\nAlle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt.\nGeringe Macht:\nReinigungsprotokoll\nCa. 2 Procs pro Minute MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu.\n\"Wenn extreme Präzision gefragt ist.\"" }
entries[168860] = { ["name"] = "Verstärkte Reinigungsprotokolle", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Reinigungsprotokoll'.\nErfordert einen respektvollen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Rostbolzenwiderstand, um diese Essenz freizuschalten.\nGroße Macht:\nLäuternde Druckwelle\n40 Meter Reichweite Sofort 1 min Abklingzeit Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\nWenn ein Gegner innerhalb des Strahls stirbt, wird Euer Schaden 8 Sek. lang um 10% erhöht.\n\nAlle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt.\nGeringe Macht:\nReinigungsprotokoll\nCa. 2 Procs pro Minute MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1.25) * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu.\n\"Wenn bisherige Protokolle wirkungslos blieben.\"" }
entries[168861] = { ["name"] = "Ultimative Reinigungsprotokolle", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Reinigungsprotokoll'.\nGroße Macht:\nLäuternde Druckwelle\n40 Meter Reichweite Sofort 1 min Abklingzeit Ruft einen läuternden Strahl auf das Zielgebiet herab, der [ 395 * (1 + Vielseitigkeit) * 7] Feuerschaden im Verlauf von 6 Sek. verursacht. Hat eine geringe Chance, alle von MUTTER für unwürdig befundenen Kreaturen sofort zu töten.\n\nWenn ein Gegner innerhalb des Strahls stirbt, wird Euer Schaden 8 Sek. lang um 10% erhöht.\n\nAlle vom Strahl getroffenen Entartungen werden für 3 Sek. betäubt.\nGeringe Macht:\nReinigungsprotokoll\nCa. 2 Procs pro Minute MUTTER hat Euer Herz von Azeroth um ein Reinigungsprotokoll erweitert, durch das Eure Schaden verursachenden Zauber und Fähigkeiten Euer Ziel mit Azeritenergie überziehen können, die 8 Sek. lang alle 2 Sek. jedem Gegner innerhalb von 8 Metern [ 563 * (1.25) * (1 + Vielseitigkeit)] Feuerschaden zufügt und Euch dabei um [ 255 * (1 + Vielseitigkeit)] Gesundheit heilt.\n\n'Reinigungsprotokoll' fügt Entartungen 50% mehr Schaden zu.\n\"Wenn alles andere versagt.\"" }
entries[168862] = { ["name"] = "F.L.U.G.-Peilsender", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nVölker: Gnom\nBenutzen: Erbittet Abholung zum nächsten Flugmeister.\n\nKann nur in Gebieten eingesetzt werden, in denen Ihr die Nutzung der Flugpfeife freigeschaltet habt.\nVerkaufspreis:" }
entries[168863] = { ["name"] = "Ungebundene Azeritspäne", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die Ungezügelte Kraft'.\nErfordert einen freundlichen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen freundlichen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nDie Ungezügelte Kraft\n40 Meter Reichweite Sofort 1 min Abklingzeit Entfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [Quellwert] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%.\nGeringe Macht:\nTollkühne Kraft\nCa. 20 Procs pro Minute Wenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 4 Sek. lang um 50% erhöht.", ["unresolvedValues"] = true }
entries[168864] = { ["name"] = "Scharfe Azeritspäne", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die Ungezügelte Kraft'.\nErfordert einen wohlwollenden Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen wohlwollenden Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nDie Ungezügelte Kraft\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Entfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [Quellwert] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%.\nGeringe Macht:\nTollkühne Kraft\nWenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 4 Sek. lang um 70% erhöht.", ["unresolvedValues"] = true }
entries[168865] = { ["name"] = "Polarisierte Azeritspäne", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die Ungezügelte Kraft'.\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Ruf in Nazjatar, um diese Essenz freizuschalten.\nErfordert einen respektvollen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen respektvollen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nDie Ungezügelte Kraft\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Entfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [Quellwert] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%.\n\nBei jedem kritischen Treffer durch 'Die Ungezügelte Kraft' wird das Ziel sofort von einem zusätzlichen Azeritsplitter getroffen (bis zu maximal 5 Splitter).\nGeringe Macht:\nTollkühne Kraft\nWenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 6 Sek. lang um 70% erhöht.", ["unresolvedValues"] = true }
entries[168866] = { ["name"] = "Glühende Azeritspäne", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die Ungezügelte Kraft'.\nGroße Macht:\nDie Ungezügelte Kraft\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Entfesselt die Kräfte in Eurem Herz von Azeroth und schießt Azeritsplitter auf Euer Ziel, das dadurch im Verlauf von 2 Sek. [Quellwert] Feuerschaden erleidet. Bei einem kritischen Treffer erhöht sich dieser Schaden um 300%.\n\nBei jedem kritischen Treffer durch 'Die Ungezügelte Kraft' wird das Ziel sofort von einem zusätzlichen Azeritsplitter getroffen (bis zu maximal 5 Splitter).\nGeringe Macht:\nTollkühne Kraft\nWenn eine Eurer Fähigkeiten nicht kritisch trifft, besteht eine hohe Chance, dass Ihr 'Tollkühne Kraft' erhaltet. Wenn 'Tollkühne Kraft' 20 Stapel erreicht, wird Euer kritischer Trefferwert 6 Sek. lang um 70% erhöht.", ["unresolvedValues"] = true }
entries[168867] = { ["name"] = "Befehle der Königin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Schriftrolle trägt das Siegel der Dunklen Fürstin. Das Pergament duftet leicht nach Rosen.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[168868] = { ["name"] = "Za'quls Schulterstücke", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n16 Rüstung\n+10 [Stärke oder Intelligenz]\n+11 Ausdauer\nHaltbarkeit 100 / 100\n\nAktive Azeritische Kräfte (0/5):\n- Eine neue Macht ist verfügbar. - Eine neue Macht ist verfügbar. - Eine neue Macht ist verfügbar. - Eine neue Macht ist verfügbar. - Azeritverstärkt ist verfügbar.\nVerkaufspreis:" }
entries[168869] = { ["name"] = "Großgürtel des Ewigkeitshüters", ["text"] = "Wird beim Aufheben gebunden\nTaille Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+8 Ausdauer\nErhöht Eure kritische Trefferwertung um + 7.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 55 / 55\nAnlegen: Der Sturm der Ewigen erhebt sich alle 2 Min. für 10 Sek. und fügt einem zufälligen Gegner innerhalb von 60 Metern 3-mal [ 64 * (1 + Vielseitigkeit)] Arkanschaden zu.\n\nAlle Effekte des Sturms der Ewigen treten gleichzeitig auf.\nVerkaufspreis:" }
entries[168870] = { ["name"] = "Würgetanghüfttuch", ["text"] = "Wird beim Aufheben gebunden\nTaille Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+8 Ausdauer\nErhöht Eure kritische Trefferwertung um + 7.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[168871] = { ["name"] = "Hüfttuch der geliebten Monarchin", ["text"] = "Wird beim Aufheben gebunden\nTaille Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+8 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 7.\nHaltbarkeit 55 / 55\nAnlegen: Der Sturm der Ewigen erhebt sich alle 2 Min. für 10 Sek. und gewährt 43 kritischen Trefferwert. Dieser Wert wird gleichmäßig zwischen Euch und Euren Verbündeten aufgeteilt.\n\nAlle Effekte des Sturms der Ewigen treten gleichzeitig auf.\nVerkaufspreis:" }
