entries[168873] = { ["name"] = "Kriegsbeinschützer der Gezeitengöttin", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n20 Rüstung\n+7 [Stärke oder Intelligenz]\n+10 Ausdauer\n+ 6 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 8.\nHaltbarkeit 120 / 120\nAnlegen: Der Sturm der Ewigen erhebt sich alle 2 Min. für 10 Sek. und gewährt 43 kritischen Trefferwert. Dieser Wert wird gleichmäßig zwischen Euch und Euren Verbündeten aufgeteilt.\n\nAlle Effekte des Sturms der Ewigen treten gleichzeitig auf.\nVerkaufspreis:" }
