entries[168920] = { ["name"] = "Azeritüberkrusteter Zeitquarz", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Kunstwerk der Zeit'.\nGroße Macht:\nStillstand\n40 Meter Reichweite Sofort 3 min Abklingzeit Erschafft einen Zeitvortex um ein verbündetes Ziel, der 4 Sek. lang 34942 Schaden und 34942 Heilung absorbiert. Wenn der Effekt abläuft, werden der absorbierte Schaden und die absorbierte Heilung im Verlauf von 10 Sek. erlitten bzw. erhalten .\nGeringe Macht:\nKunstwerk der Zeit\nCa. 10 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel für 6 Sek. 72 Tempo zu gewähren.\n\"Es gibt immer Zeit für eine Kampfpause.\"" }
entries[168921] = { ["name"] = "Azeritversetzter Zeitquarz", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Kunstwerk der Zeit'.\nErfordert den Erfolg \"Schlachtfeldraufbold\". (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nStillstand\n40 Meter Reichweite Sofort 3 min Abklingzeit Erschafft einen Zeitvortex um ein verbündetes Ziel, der 6 Sek. lang 34942 Schaden und 34942 Heilung absorbiert. Wenn der Effekt abläuft, werden der absorbierte Schaden und die absorbierte Heilung im Verlauf von 10 Sek. erlitten bzw. erhalten .\nGeringe Macht:\nKunstwerk der Zeit\nCa. 10 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel für 8 Sek. 86 Tempo zu gewähren.\n\"Es gibt immer Zeit für eine Kampfpause.\"" }
entries[168922] = { ["name"] = "Azeritbetriebener Zeitquarz", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Kunstwerk der Zeit'.\nErfordert den Erfolg \"Schlachtfeldtaktiker\". (Kauf nicht möglich, wenn bereits bekannt)\nErlernt Rang 3 vom Blut des Feindes, des Kunstwerks der Zeit oder der Sphäre der Unterdrückung auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nStillstand\n40 Meter Reichweite Sofort 3 min Abklingzeit Erschafft einen Zeitvortex um ein verbündetes Ziel, der 6 Sek. lang 34942 Schaden und 34942 Heilung absorbiert. Wenn der Effekt abläuft, werden der absorbierte Schaden und die absorbierte Heilung im Verlauf von 10 Sek. erlitten bzw. erhalten und der Schaden wird um 20% verringert.\nGeringe Macht:\nKunstwerk der Zeit\nCa. 10 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel für 8 Sek. 86 Tempo und 72 Geschwindigkeit zu gewähren.\n\"Es gibt immer Zeit für eine Kampfpause.\"" }
entries[168923] = { ["name"] = "Unbelasteter Azeritzeitquartz", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Kunstwerk der Zeit'.\nGroße Macht:\nStillstand\n40 Meter Reichweite Sofort 3 min Abklingzeit Erschafft einen Zeitvortex um ein verbündetes Ziel, der 6 Sek. lang 34942 Schaden und 34942 Heilung absorbiert. Wenn der Effekt abläuft, werden der absorbierte Schaden und die absorbierte Heilung im Verlauf von 10 Sek. erlitten bzw. erhalten und der Schaden wird um 20% verringert.\nGeringe Macht:\nKunstwerk der Zeit\nCa. 10 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel für 8 Sek. 86 Tempo und 72 Geschwindigkeit zu gewähren.\n\"Es gibt immer Zeit für eine Kampfpause.\"" }
entries[168924] = { ["name"] = "Pralle Saat des Lebens", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Invokation der Lebensbinderin'.\nGroße Macht:\nInvokation der Lebensbinderin\nWirken in 2.5 sek. 2.5 min Abklingzeit Pflanzt 30 Samen von Eonar ein, die auf alle Verbündeten innerhalb von 30 Metern verteilt werden.\n\nSamen von Eonar\nWenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\nGeringe Macht:\nSamen von Eonar\nCa. 15 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel einen Samen von Eonar einzupflanzen, der 12 Sek. lang bestehen bleibt.\n\nSamen von Eonar\nWenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\n\"Eonar überschüttete Azeroth mit den ersten Samenkörnern des Lebens, doch nur in wenigen ist noch die Macht der Titanen erhalten.\"" }
entries[168925] = { ["name"] = "Reproduzierende Saat des Überflusses", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Invokation der Lebensbinderin'.\nGroße Macht:\nInvokation der Lebensbinderin\nWirken in 2.5 sek. 2.5 min Abklingzeit Pflanzt 40 Samen von Eonar ein, die auf alle Verbündeten innerhalb von 30 Metern verteilt werden.\n\nSamen von Eonar\nWenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\nGeringe Macht:\nSamen von Eonar\nCa. 15 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel einen Samen von Eonar einzupflanzen, der 15 Sek. lang bestehen bleibt.\n\nSamen von Eonar\nWenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\n\"Eonar überschüttete Azeroth mit den ersten Samenkörnern des Lebens, doch nur in wenigen ist noch die Macht der Titanen erhalten.\"" }
entries[168926] = { ["name"] = "Verbleibende Saat der Erneuerung", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Invokation der Lebensbinderin'.\nErlernt Rang 3 der Essenz der Fokussierungsiris, der Invokation der Lebensbinderin oder der Anima von Leben und Tod auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nInvokation der Lebensbinderin\nWirken in 2.5 sek. 2.5 min Abklingzeit Pflanzt 40 Samen von Eonar ein, die auf alle Verbündeten innerhalb von 30 Metern verteilt werden.\n\nWenn Samen ungenutzt ablaufen, wird die Abklingzeit dieser Fähigkeit um 2 Sek. verringert.\n\nSamen von Eonar\nHeilt alle 1 Sek. um 21 Gesundheit. Wenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\nGeringe Macht:\nSamen von Eonar\nCa. 15 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel einen Samen von Eonar einzupflanzen, der 15 Sek. lang bestehen bleibt.\n\nSamen von Eonar\nHeilt alle 1 Sek. um 21 Gesundheit. Wenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\n\"Eonar überschüttete Azeroth mit den ersten Samenkörnern des Lebens, doch nur in wenigen ist noch die Macht der Titanen erhalten.\"" }
entries[168927] = { ["name"] = "Samen farbenprächtiger Blüten", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Invokation der Lebensbinderin'.\nGroße Macht:\nInvokation der Lebensbinderin\nWirken in 2.5 sek. 2.5 min Abklingzeit Pflanzt 40 Samen von Eonar ein, die auf alle Verbündeten innerhalb von 30 Metern verteilt werden.\n\nWenn Samen ungenutzt ablaufen, wird die Abklingzeit dieser Fähigkeit um 2 Sek. verringert.\n\nSamen von Eonar\nHeilt alle 1 Sek. um 21 Gesundheit. Wenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\nGeringe Macht:\nSamen von Eonar\nCa. 15 Procs pro Minute Eure Heilungen haben eine sehr hohe Chance, dem Ziel einen Samen von Eonar einzupflanzen, der 15 Sek. lang bestehen bleibt.\n\nSamen von Eonar\nHeilt alle 1 Sek. um 21 Gesundheit. Wenn das Ziel Schaden erleidet, bricht die Saat auf und heilt es um 436 .\n\"Eonar überschüttete Azeroth mit den ersten Samenkörnern des Lebens, doch nur in wenigen ist noch die Macht der Titanen erhalten.\"" }
entries[168928] = { ["name"] = "Tafel der ausgleichenden Fluten", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die unerschöpfliche Flut'.\nErfordert einen freundlichen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen freundlichen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nMana überladen\nSofort 30 sek. Abklingzeit Überlädt Euer Mana für 8 Sek., sodass jeder Eurer gewirkten Zauber Eure Heilung pro Stapel um 3% erhöht.\n\nWährend der Überladung steht Eure Manaregeneration still .\nGeringe Macht:\nDie unerschöpfliche Flut\nCa. 1.75 Procs pro Minute Eure Heilungen haben die Chance, Euch 477 Mana oder 10 Sek. lang 115 Intelligenz zu gewähren. Die Chance auf den Erhalt von Mana erhöht sich im Verhältnis zu Eurem verbrauchten Mana. (3.5s Abklingzeit)\n\"Das Geflüster von Elune und Neptulon wirkt auf die Fluten ein. Ihre in Stein verewigten Worte sind ein Tribut an das Gleichgewicht ihrer Kräfte.\"" }
entries[168929] = { ["name"] = "Kodex der unendlichen Fluten", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die unerschöpfliche Flut'.\nErfordert einen wohlwollenden Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen wohlwollenden Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nMana überladen\nSofort 30 sek. Abklingzeit Überlädt Euer Mana für 8 Sek., sodass jeder Eurer gewirkten Zauber Eure Heilung pro Stapel um 4% erhöht.\n\nWährend der Überladung steht Eure Manaregeneration still .\nGeringe Macht:\nDie unerschöpfliche Flut\nCa. 1.75 Procs pro Minute Eure Heilungen haben die Chance, Euch [Quellwert] Mana oder 10 Sek. lang [Quellwert] Intelligenz zu gewähren. Die Chance auf den Erhalt von Mana erhöht sich im Verhältnis zu Eurem verbrauchten Mana. [Die unerschöpfliche Flut: Chance von 20%, beide Effekte zu erhalten ] (3.5s Abklingzeit)", ["unresolvedValues"] = true }
entries[168930] = { ["name"] = "Foliant der beschleunigenden Fluten", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die unerschöpfliche Flut'.\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Ruf in Nazjatar, um diese Essenz freizuschalten.\nErfordert einen respektvollen Ruf bei den Entfesselten. (Kauf nicht möglich, wenn bereits bekannt)\nErfordert einen respektvollen Ruf bei den Ankoanern. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nMana überladen\nSofort 30 sek. Abklingzeit Überlädt Euer Mana für 8 Sek., sodass jeder Eurer gewirkten Zauber Eure Heilung pro Stapel um 4% erhöht.\n\nWährend der Überladung steht Eure Manaregeneration still und Ihr erhaltet 10% Tempo.\nGeringe Macht:\nDie unerschöpfliche Flut\nCa. 1.75 Procs pro Minute Eure Heilungen haben die Chance, Euch [Quellwert] Mana oder 10 Sek. lang [Quellwert] Intelligenz zu gewähren. Die Chance auf den Erhalt von Mana erhöht sich im Verhältnis zu Eurem verbrauchten Mana. Chance von 20%, beide Effekte zu erhalten. (3.5s Abklingzeit)", ["unresolvedValues"] = true }
entries[168931] = { ["name"] = "Pergament der erleuchtenden Fluten", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Die unerschöpfliche Flut'.\nGroße Macht:\nMana überladen\nSofort 30 sek. Abklingzeit Überlädt Euer Mana für 8 Sek., sodass jeder Eurer gewirkten Zauber Eure Heilung pro Stapel um 4% erhöht.\n\nWährend der Überladung steht Eure Manaregeneration still und Ihr erhaltet 10% Tempo.\nGeringe Macht:\nDie unerschöpfliche Flut\nCa. 1.75 Procs pro Minute Eure Heilungen haben die Chance, Euch [Quellwert] Mana oder 10 Sek. lang [Quellwert] Intelligenz zu gewähren. Die Chance auf den Erhalt von Mana erhöht sich im Verhältnis zu Eurem verbrauchten Mana. Chance von 20%, beide Effekte zu erhalten. (3.5s Abklingzeit)", ["unresolvedValues"] = true }
entries[168932] = { ["name"] = "Batterie des reaktiven Seins", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Der Quell des Seins'.\nErfordert einen freundlichen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nErfrischung\n100 Meter Reichweite Sofort 15 sek. Abklingzeit Gibt sämtliche im Quell des Seins gespeicherte Heilung an einen Verbündeten ab. Diese Heilung wird um 20 % verstärkt.\nGeringe Macht:\nDer Quell des Seins\n15% Eurer überschüssigen Heilung wird im Quell des Seins gespeichert. Wenn Ihr ein Ziel heilt, dessen Gesundheit unter 40% liegt, gewährt der Quell ihm einen Teil der gespeicherten Heilung in Höhe von bis zu 547 Gesundheit." }
entries[168933] = { ["name"] = "Kondensator des verbesserten Seins", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Der Quell des Seins'.\nErfordert einen wohlwollenden Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nGroße Macht:\nErfrischung\n100 Meter Reichweite Sofort 15 sek. Abklingzeit Gibt sämtliche im Quell des Seins gespeicherte Heilung an einen Verbündeten ab. Diese Heilung wird um 50% verstärkt.\nGeringe Macht:\nDer Quell des Seins\n15% Eurer überschüssigen Heilung wird im Quell des Seins gespeichert. Wenn Ihr ein Ziel heilt, dessen Gesundheit unter 50% liegt, gewährt der Quell ihm einen Teil der gespeicherten Heilung in Höhe von bis zu 547 Gesundheit." }
entries[168934] = { ["name"] = "Kalibrierte Anzeige des Seins", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Der Quell des Seins'.\nErfordert einen respektvollen Ruf beim Rostbolzenwiderstand. (Kauf nicht möglich, wenn bereits bekannt)\nErlernt mit einem anderen Charakter eine beliebige Essenz von Rang 3 über den Rostbolzenwiderstand, um diese Essenz freizuschalten.\nGroße Macht:\nErfrischung\n100 Meter Reichweite Sofort 15 sek. Abklingzeit Gibt sämtliche im Quell des Seins gespeicherte Heilung an einen Verbündeten ab. Diese Heilung wird um 50% verstärkt. Der Quell gibt nicht mehr Heilung ab, als nötig ist, um das Ziel vollständig zu heilen.\nGeringe Macht:\nDer Quell des Seins\n15% Eurer überschüssigen Heilung wird im Quell des Seins gespeichert. Wenn Ihr ein Ziel heilt, dessen Gesundheit unter 50% liegt, gewährt der Quell ihm einen Teil der gespeicherten Heilung in Höhe von bis zu 547 Gesundheit.\n\nWenn der Quell weniger als 1398 Heilung enthält, absorbiert er Heilung doppelt so schnell." }
entries[168935] = { ["name"] = "Intensitätsanzeige des Seins", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Der Quell des Seins'.\nGroße Macht:\nErfrischung\n100 Meter Reichweite Sofort 15 sek. Abklingzeit Gibt sämtliche im Quell des Seins gespeicherte Heilung an einen Verbündeten ab. Diese Heilung wird um 50% verstärkt. Der Quell gibt nicht mehr Heilung ab, als nötig ist, um das Ziel vollständig zu heilen.\nGeringe Macht:\nDer Quell des Seins\n15% Eurer überschüssigen Heilung wird im Quell des Seins gespeichert. Wenn Ihr ein Ziel heilt, dessen Gesundheit unter 50% liegt, gewährt der Quell ihm einen Teil der gespeicherten Heilung in Höhe von bis zu 547 Gesundheit.\n\nWenn der Quell weniger als 1398 Heilung enthält, absorbiert er Heilung doppelt so schnell." }
entries[168936] = { ["name"] = "Schutz der unerschütterlichen Hoffnung", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Unnachgiebiger Schutz'.\nGroße Macht:\nWächtersphäre\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit Entsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert.\nGeringe Macht:\nUnnachgiebiger Schutz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu [ 848 * (1 + Vielseitigkeit)]-mal stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168937] = { ["name"] = "Schutz der Erwiderung", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Unnachgiebiger Schutz'.\nGroße Macht:\nWächtersphäre\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit Entsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert.\n\nJedes Mal, wenn Ihr eine Schutzsphäre entsendet, erhaltet Ihr einen Absorptionsschild in Höhe von 2% Eurer maximalen Gesundheit.\nGeringe Macht:\nUnnachgiebiger Schutz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu einem Maximum von [ 848 * (1 + Vielseitigkeit) * (1.2)] stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht.\n\"Wer anderen hilft...\"" }
entries[168938] = { ["name"] = "Schutz der gegenseitigen Hilfe", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Unnachgiebiger Schutz'.\nErlernt Rang 3 einer Essenz aus Verstörenden Visionen auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nWächtersphäre\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit Entsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert.\n\nJedes Mal, wenn Ihr eine Schutzsphäre entsendet, erhaltet Ihr einen Absorptionsschild in Höhe von 2% Eurer maximalen Gesundheit.\n\nWenn ein Verbündeter den Absorptionsschild erhält, werden Ihr und Euer Verbündeter um [ 346 * (1 + Vielseitigkeit)] Gesundheit geheilt.\nGeringe Macht:\nUnnachgiebiger Schutz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu [ 848 * (1 + Vielseitigkeit) * (1.2)]-mal stapelbar.\n\nVon 'Unnachgiebiger Schutz' geschützte Ziele erleiden 3% weniger Schaden.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168939] = { ["name"] = "Osmenitsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Einige kleine, nicht verwertbare Splitter Osmenit.\"" }
entries[168940] = { ["name"] = "Schutz der Unvorstellbaren Brillanz", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Unnachgiebiger Schutz'.\nGroße Macht:\nWächtersphäre\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit Entsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert.\n\nJedes Mal, wenn Ihr eine Schutzsphäre entsendet, erhaltet Ihr einen Absorptionsschild in Höhe von 2% Eurer maximalen Gesundheit.\n\nWenn ein Verbündeter den Absorptionsschild erhält, werden Ihr und Euer Verbündeter um [ 346 * (1 + Vielseitigkeit)] Gesundheit geheilt.\nGeringe Macht:\nUnnachgiebiger Schutz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu [ 848 * (1 + Vielseitigkeit) * (1.2)]-mal stapelbar.\n\nVon 'Unnachgiebiger Schutz' geschützte Ziele erleiden 3% weniger Schaden.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[168941] = { ["name"] = "Vitalitätsumverteilungsgitterwerk", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vitalitätsverbindung'.\nGroße Macht:\nVitalitätsverbindung\n40 Meter Reichweite Sofort 1 min Abklingzeit Richtet die Vitalitätsverbindung auf einen Verbündeten. Dadurch transferiert dieser 6 Sek. lang alle 0.5 Sek. [ 958 * (1 + Vielseitigkeit)] Gesundheit vom Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern.\nGeringe Macht:\nÜbertragung\nCa. 15 Procs pro Minute Die Ziele Eurer Heilungen haben eine sehr hohe Chance, [ 958 * (1 + Vielseitigkeit)] Gesundheit von dem Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern zu transferieren." }
entries[168942] = { ["name"] = "Maschen dehnbarer Vitalität", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vitalitätsverbindung'.\nGroße Macht:\nVitalitätsverbindung\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Richtet die Vitalitätsverbindung auf einen Verbündeten. Dadurch transferiert dieser 6 Sek. lang alle 0.5 Sek. [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit vom Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern.\nGeringe Macht:\nÜbertragung\nCa. 15 Procs pro Minute Die Ziele Eurer Heilungen haben eine sehr hohe Chance, [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit von dem Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern zu transferieren." }
entries[168943] = { ["name"] = "Gitter überbordender Vitalität", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vitalitätsverbindung'.\nErlernt Rang 3 der Kondensierten Lebenskraft, der Vitalitätsverbindung oder von Azeroths unsterblichem Geschenk auf einem anderen Charakter, um diese Essenz freizuschalten.\nGroße Macht:\nVitalitätsverbindung\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Richtet die Vitalitätsverbindung auf einen Verbündeten. Dadurch transferiert dieser 6 Sek. lang alle 0.5 Sek. [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit vom Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern.\n\nWenn das Ziel seine volle Gesundheit erreicht, springt der Effekt für die verbleibende Dauer auf das Ziel mit der niedrigsten Gesundheit in der Nähe über.\nGeringe Macht:\nÜbertragung\nCa. 15 Procs pro Minute Die Ziele Eurer Heilungen haben eine sehr hohe Chance, [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit von dem Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern zu transferieren.\n\nGesundheitstransfers hinterlassen 5 Sek. lang einen Schild auf dem Ziel, der 575 Schaden absorbiert." }
entries[168944] = { ["name"] = "Netz ungezügelter Vitalität", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin , Priester , Schamane , Mönch , Druide , Rufer\nBenutzen: Verleiht Eurem Herz von Azeroth 'Vitalitätsverbindung'.\nGroße Macht:\nVitalitätsverbindung\n40 Meter Reichweite Sofort 45 sek. Abklingzeit Richtet die Vitalitätsverbindung auf einen Verbündeten. Dadurch transferiert dieser 6 Sek. lang alle 0.5 Sek. [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit vom Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern.\n\nWenn das Ziel seine volle Gesundheit erreicht, springt der Effekt für die verbleibende Dauer auf das Ziel mit der niedrigsten Gesundheit in der Nähe über.\nGeringe Macht:\nÜbertragung\nCa. 15 Procs pro Minute Die Ziele Eurer Heilungen haben eine sehr hohe Chance, [ 958 * 1.2 * (1 + Vielseitigkeit)] Gesundheit von dem Verbündeten mit der höchsten Gesundheit innerhalb von 30 Metern zu transferieren.\n\nGesundheitstransfers hinterlassen 5 Sek. lang einen Schild auf dem Ziel, der 575 Schaden absorbiert." }
entries[168946] = { ["name"] = "Bündel wiederverwertbarer Teile", ["text"] = "Wird beim Aufheben gebunden" }
entries[168947] = { ["name"] = "Schriftrolle überbordender Macht", ["text"] = "Questgegenstand\nBenutzen: Probiert Kojos neue Schriftrolle an einem nichts ahnenden Terrorschlund der Schnappdrachen aus!\n\nKann nur in Nar'anan verwendet werden. (10 Sek. Abklingzeit)" }
entries[168948] = { ["name"] = "Getrockneter Tang", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Behandelt das Ziel mit getrocknetem Tang und bewirkt eine schnelle Wundheilung." }
entries[168949] = { ["name"] = "Dehnbare Antriebswelle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 0 gehärtete Sprungfedern, 0 gehärtete Panzerungen und 0 verarbeitete Getriebe, um ein Bündel wiederverwertbarer Teile zu erhalten.\nVerkaufspreis:" }
entries[168954] = { ["name"] = "Osmenitstaub", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Selbst als Erzstaub glänzt Osmenit immer noch herrlich.\"" }
entries[168955] = { ["name"] = "Elektrifizierender Kognitivverstärker", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n4 - 6 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+21 Intelligenz\n+5 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 3 Vielseitigkeit\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[168956] = { ["name"] = "Vertrag: Ankoaner", ["text"] = "Benutzen: Schließt einen Vertrag mit den Ankoanern ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in Kul Tiras oder Zandalar abschließt.\nBenötigt Ankoaner der Meeresklinge\n- Freundlich\nVerkaufspreis:" }
entries[168957] = { ["name"] = "Meisterschaftsgürtel des Robogenieurs", ["text"] = "Wird beim Aufheben gebunden\nTaille Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+8 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[168958] = { ["name"] = "Kummerbund des Ringmeisters", ["text"] = "Wird beim Aufheben gebunden\nTaille Stoff\n3 Rüstung\n+5 Intelligenz\n+8 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 6 Vielseitigkeit\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[168959] = { ["name"] = "Vertrag: Die Entfesselten", ["text"] = "Benutzen: Schließt einen Vertrag mit den Entfesselten ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in Kul Tiras oder Zandalar abschließt.\nBenötigt Die Entfesselten\n- Freundlich\nVerkaufspreis:" }
entries[168960] = { ["name"] = "Vertrag: Der Rostbolzenwiderstand", ["text"] = "Benutzen: Schließt einen Vertrag mit dem Rostbolzenwiderstand ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in Kul Tiras oder Zandalar abschließt.\nBenötigt Rostbolzenwiderstand\n- Freundlich\nVerkaufspreis:" }
entries[168961] = { ["name"] = "Exotherme Verdampferspule", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde (Realzeit)\nBenutzen: In der Wetteränderungsmaschine installieren, um sie zu aktivieren.\n\"Ein experimenteller Wärmetauscher. Korrodiert schnell, wenn man ihn von einer Energiequelle trennt.\"" }
entries[168962] = { ["name"] = "Apexperforator", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n5 - 9 Schaden Geschwindigkeit 1.80\n(3.9 Schaden pro Sekunde)\n+4 Beweglichkeit\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
entries[168963] = { ["name"] = "Fusionshacker", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n6 - 14 Schaden Geschwindigkeit 2.60\n(3.8 Schaden pro Sekunde)\n+4 Stärke\n+5 Ausdauer\nHaltbarkeit 110 / 110\nAnlegen: Eure Nahkampfangriffe haben eine Chance, Euren Gegner mit Fusionsfeuer zu entzünden, und ihm so im Verlauf von 4 Sek. ( 7 * 4) Feuerschaden zuzufügen.\nVerkaufspreis:" }
entries[168964] = { ["name"] = "Hyperfadenstiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n4 Rüstung\n+5 Intelligenz\n+8 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 7.\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
entries[168965] = { ["name"] = "Modulare Platinpanzerung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nBenutzen: Gewährt 30 Sek. lang 4 Stapel von 'Platinpanzerung', was Eure Rüstung um 68 erhöht. Wenn ein körperlicher Schadenseffekt Euch mehr als 10% Eurer Gesundheit als Schaden zufügt, wird ein Stapel von 'Platinpanzerung' entfernt. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
