entries[169162] = { ["name"] = "Wunderschwinge 2.0", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Fragt nicht, was mit der ersten Version geschehen ist... Die Technologie von Mechagon ist schließlich immer noch Gnomtechnologie!\"\nErfolg:\nPfadfinder von Battle for Azeroth, Teil zwei\nKategorie:\nBattle for Azeroth" }
entries[169163] = { ["name"] = "Leisegleiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die von Natur aus in dieser Kreatur gespeicherten Gase ermöglichen es ihr, sowohl in den Tiefen zu überleben als auch in der Luft zu schweben.\"\nBeute von:\nLautlos\nZone:\nNazjatar" }
