entries[169194] = { ["name"] = "Schnapprückenkrabbler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Riesenkrabben sind in Nazjatar einheimisch und ein beliebtes Nahrungsmittel für die Naga. Diese hier muss gut versorgt worden sein, um so groß zu werden.\"\nErfolg:\nUnterwasserusurpator\nKategorie:\nBattle for Azeroth" }
entries[169195] = { ["name"] = "Goldgrille", ["text"] = "Wird beim Aufheben gebunden\n\"Lehrt Euch, wie man dieses Haustier beschwört.\"\nVerkaufspreis:" }
entries[169196] = { ["name"] = "Ausrüstungstruhe der Kriegsfront", ["text"] = "Heroisch\nWird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"" }
entries[169197] = { ["name"] = "Ausrüstungstruhe der Kriegsfront", ["text"] = "Heroisch\nWird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"" }
entries[169198] = { ["name"] = "Königlicher Schnappdrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Schnappdrachen werden schon jung gefangen und darauf trainiert, den Jägern der Naga zu dienen. Sie sind treue und erbitterte Begleiter.\"\nBeute von:\nVorräte der Ankoaner\nBeute von:\nVorräte der Entfesselten" }
entries[169199] = { ["name"] = "Schnappdrachentangpirscher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn ein Schnappdrache zubeißt, sind die Bisspuren selbst nicht zu beachtlich, doch wenn das Gift das Fleisch um die Wunde zerfrisst, wird es unangenehm.\"\nQuest:\nBraves Mädchen\nZone:\nNazjatar" }
entries[169200] = { ["name"] = "Tiefenkorallenschnappdrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Im Wasser ist dieser Schnappdrache ein leiser Jäger, doch auf dem Land kann er sich nicht gerade gut verbergen.\"\nQuest:\nGezähmte Wildheit\nZone:\nNazjatar" }
entries[169201] = { ["name"] = "Fabius", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er erhebt sich aus dem Wasser, seine Flossen schwingen locker im Wind, die Sonne lässt seine Schuppen glitzern. Er ist einfach... fabihaft.\"\nBeute von:" }
entries[169202] = { ["name"] = "Blutroter Gezeitenhengst", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dank ihrer blutroten Färbung können diese Wesen sich ausgezeichnet zwischen Korallenformationen verstecken.\"\nVerkäufer:\nMrrl\nZone:\nNazjatar\nKosten:\n4\n2\n1" }
entries[169203] = { ["name"] = "Tintengeschuppter Tiefensucher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Gezeitenhengste jagen in Schwärmen, indem sie ihre Beute immer und immer wieder mit ihren muskulösen Brustkörben rammen.\"\nVerkäufer:\nMagor Geistbeuger\nZone:\nNazjatar\nKosten:\n150\n\nVerkäufer:\nDazzerian\nZone:\nNazjatar\nKosten:\n150" }
entries[169205] = { ["name"] = "Geisterhafter Welpling", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren geisterhaften Welpling beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[169207] = { ["name"] = "Erinnerungskern", ["text"] = "Questgegenstand\n\"Kann in einen Erinnerungspylonen eingesteckt werden, um eine lang vergessene Erinnerung abzuspielen. Jemand wollte das vor neugierigen Blicken schützen...\"" }
entries[169208] = { ["name"] = "Krone des immerwährenden Glücks", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Ein Blumenkranz, der seinem Träger das ganze Jahr Glück bescheren soll.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[169209] = { ["name"] = "Schriftrolle überbordender Macht", ["text"] = "Questgegenstand\nBenutzen: Kanalisiert die Schriftrolle auf die Schnappdrachenmatriarchin.\n\nKann nur in Nar'anan verwendet werden. (1 Min Abklingzeit)" }
