entries[169223] = { ["name"] = "Ashjra'kamas, Tuch der Entschlossenheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRücken\n7 Rüstung\n+6 [Beweglichkeit oder Stärke oder Intelligenz]\n+9 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nVerkaufspreis:" }
