entries[169227] = { ["name"] = "Verstrahlte Bolzen", ["text"] = "Questgegenstand\n\"Wer hat das gebaut, und hat derjenige es überlebt?\"" }
entries[169228] = { ["name"] = "Gefahrgutcontainer", ["text"] = "Questgegenstand\n\"Eine raffinierte Lösung zur internen Aufbewahrung gefährlicher Nebenprodukte.\"" }
