entries[169234] = { ["name"] = "Frisches Unagi", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Mehr als ein paar Augenblicke auf dem Grill braucht es nicht... und vielleicht ein wenig Sauce.\"\nVerkaufspreis:" }
