entries[169253] = { ["name"] = "Muschelhorn", ["text"] = "Questgegenstand\n\"Wenn Ihr hineinblast, stößt es ein grollendes Geräusch aus.\"" }
entries[169255] = { ["name"] = "Büschel rotes Fell", ["text"] = "Questgegenstand\n\"Wurde es für Ritual- oder Modezwecke eingefärbt?\"" }
entries[169257] = { ["name"] = "Gezackte Rune", ["text"] = "Questgegenstand\n\"Ist sie kaputt, oder versteht Ihr sie nur einfach nicht zu benutzen?\"" }
