entries[169288] = { ["name"] = "Armplatten des Schwarzzahngrunzers", ["text"] = "Wird beim Anlegen gebunden\nHandgelenk Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 2 Vielseitigkeit\nHaltbarkeit 40 / 40\nVerkaufspreis:" }
entries[169289] = { ["name"] = "Geplünderter Kürbisstampfer", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Streitkolben\n8 - 10 Schaden Geschwindigkeit 2.60\n(3.5 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\n+ 3 Vielseitigkeit\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[169290] = { ["name"] = "Geplünderter Schwarzzahngesichtsteiler", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Axt\n6 - 13 Schaden Geschwindigkeit 2.60\n(3.7 Schaden pro Sekunde)\n+3 Stärke\n+5 Ausdauer\n+ 3 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[169292] = { ["name"] = "Aufgeladene Schuppe des Blauen Aspekts", ["text"] = "Questgegenstand\n\"Die Schuppe weist ein eisiges Schimmern auf.\"" }
entries[169293] = { ["name"] = "Manifestierte Visionen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 200 manifestierte Visionen, um ein Gefäß der verstörenden Visionen zu erschaffen.\nVerkaufspreis:" }
entries[169294] = { ["name"] = "Widerstandsfähige Seele", ["text"] = "Vision der Wirbelnden Sande\nEinzigartig (5)\nBenutzen: Stellt 50 geistige Gesundheit beim Zaubernden und 50 geistige Gesundheit bei bis zu 3 Verbündeten innerhalb von 20 Metern wieder her. (1 Min Abklingzeit)\n\"Obwohl der Körper geschunden wurde, widerstand diese entschlossene Seele N'Zoths Verderbnis.\"" }
entries[169295] = { ["name"] = "Inaktiver Stein der Visionen", ["text"] = "Benutzen: Kombiniert 200 manifestierte Visionen, um ein Gefäß der verstörenden Visionen zu erschaffen.\nVerkaufspreis:" }
entries[169296] = { ["name"] = "Besudelte Seele", ["text"] = "Verkaufspreis:" }
entries[169297] = { ["name"] = "Abzeichen der Sturmlanzen", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch in das Heiligtum von Dun Baldar zurück. (2 Min Abklingzeit)" }
entries[169298] = { ["name"] = "Abzeichen der Frostwölfe", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch in das Heiligtum von Burg Frostwolf zurück. (2 Min Abklingzeit)\n\"Das Auge der Führung\"" }
entries[169299] = { ["name"] = "Trank der ungezügelten Wut", ["text"] = "Benutzen: Verleiht Euch selbst ungezügelte Energie und gewährt Euren offensiven Zaubern und Angriffen eine Chance, Eurem Ziel zusätzlich 1344 Feuerschaden zuzufügen. Hält 1 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[169300] = { ["name"] = "Trank der wilden Heilung", ["text"] = "Benutzen: Ermächtigt Euren Verstand und gewährt Euren Heilfähigkeiten eine Chance, bei Eurem Ziel zusätzlich 2017 Gesundheit wiederherzustellen. Hält 1 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[169301] = { ["name"] = "Hochgeborenenkompendium der wirbelnden Fluten", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, einem Verbündeten einen Absorptionsschild zu gewähren, der für 12 Sek. bis zu 153 Schaden absorbiert. Während der Schild besteht, ist der Primärwert des Ziels um 6 erhöht.\nVerkaufspreis:" }
entries[169302] = { ["name"] = "Hochgeborenenkompendium des mystischen Bollwerks", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nAnlegen: Wenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr um 78 Gesundheit geheilt werdet und 10 Sek. lang 9 Rüstung erhaltet. Bis zu ( 9 * 4) Rüstung stapelbar.\nVerkaufspreis:" }
entries[169303] = { ["name"] = "Armschienen des Kraftprotzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Gebt mit Euren Muskeln an und erhöht so 15 Min. lang die Armkraft. (45 Min Abklingzeit)\n\"Muskelpakete nicht inbegriffen.\"\nVerkaufspreis:" }
entries[169304] = { ["name"] = "Köder des Leviathans", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nAnlegen: Eure Schaden verursachenden Fähigkeiten haben eine sehr kleine Chance, einen Leviathan zu beschwören, der Eurem Ziel [ 165 * (1 + Vielseitigkeit)] körperlichen Schaden zufügt.\n\nEuer verursachter Schaden lässt auf Eurem Ziel außerdem leuchtende Algen wachsen, die Eure Beschwörungschance erhöhen.\nVerkaufspreis:" }
entries[169305] = { ["name"] = "Äquipotenter Nautilus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nBenutzen: Entfesselt eine Welle, die über Euer Ziel hereinbricht und zu Eurer Ausgangsposition zurückkehrt. Fügt Gegnern auf ihrem Weg im Verlauf von 4 Sek. [ 24 * (5) * (1 + Vielseitigkeit)] Frostschaden zu. Fangt die Welle ab, um die Abklingzeit um 30 Sek. zu verringern. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[169306] = { ["name"] = "Za'quls Portalschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 10.\nAnlegen: Eure Fähigkeiten haben eine geringe Chance, in der Nähe für 30 Sek. einen Leerenriss zu erschaffen. Bewegt Euch zu einem Leerenriss, um für 10 Sek. ein Portal zu öffnen. Wenn Ihr im Portal steht, erhaltet Ihr 28 Intelligenz.\nVerkaufspreis:" }
entries[169307] = { ["name"] = "Vision des Untergangs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nBenutzen: Offenbart das bevorstehende Ableben Eures Gegners und erhöht Euer Tempo 10 Sek. lang um 30 . Pro 10% Gesundheit, die Eurem Ziel fehlen, erhaltet Ihr zusätzlich 4 Tempo. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[169308] = { ["name"] = "Kette des Leidens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nBenutzen: Überträgt 25 Sek. lang 50% Eures eintreffenden Schadens auf einen Verbündeten innerhalb von 25 Metern, bis zu maximal 1644 Schaden. Der Effekt wird abgebrochen, wenn das Ziel sich außer Reichweite bewegt oder seine Gesundheit unter 25% fällt. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[169309] = { ["name"] = "Zoatroideneiersack", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nAnlegen: Beim Wirken einer Einzelzielheilung besteht die Chance, einen Zoatroiden auf Eurem Ziel zu beschwören, der [ 76 * (1 + Vielseitigkeit)] Schaden absorbiert und abhängig von der verbleibenden Absorption bis zu 11 Vielseitigkeit gewährt. Pro 10% Mana, die Ihr verbraucht, wird Euer Zoatroid genährt, was die Absorption um [ 8 * (1 + Vielseitigkeit)] und die Vielseitigkeit um 1 erhöht.\nVerkaufspreis:" }
entries[169310] = { ["name"] = "Blutrünstiger Seeigel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nAnlegen: 10% des erlittenen Schadens gewährt Euch Heilendes Blut, bis zu [ 315 * (1 + Vielseitigkeit)] insgesamt. Verbraucht alle 3 Sek. [ 41 * (1 + Vielseitigkeit)] Heilendes Blut, um Euch zu heilen, falls Ihr verwundet seid.\nVerkaufspreis:" }
entries[169311] = { ["name"] = "Aschenwinds Klingenkoralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nBenutzen: Verursacht [ 25 * (1 + Vielseitigkeit)] körperlichen Schaden und belegt Euer Ziel mit 'Klingenkoralle'. Daraufhin haben Eure Schadensfähigkeiten gegen Euer Ziel eine hohe Chance, ihm [ 25 * (1 + Vielseitigkeit)] körperlichen Schaden zuzufügen und einen Stapel von 'Klingenkoralle' hinzuzufügen.\n\nDie erneute Aktivierung dieser Fähigkeit entfernt 'Klingenkoralle' von Eurem Ziel und gewährt Euch 20 Sek. lang 3 kritischen Trefferwert pro Stapel. (20 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[169312] = { ["name"] = "Leuchtendes Quallenkraut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nAnlegen: Eure Heilungen haben eine Chance, dem am schwersten verletzten Verbündeten innerhalb von 40 Metern 'Lumineszenz' zu verleihen. Verbündete, die mit Lumineszenz belegt sind, erhalten 10% zusätzliche Heilung, bis insgesamt [ 87 * (1 + Vielseitigkeit)] zusätzliche Heilung erreicht ist.\nVerkaufspreis:" }
entries[169313] = { ["name"] = "Phiole des arkanen Sturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nAnlegen: Eure Schaden verursachenden Fähigkeiten haben eine geringe Chance, Euch 20 Sek. lang in einen arkanen Sturm zu hüllen, der Gegnern in der Nähe alle 2 Sek. 5 Arkanschaden zufügt. Jedes Mal, wenn der Sturm einem einzelnen Gegner Schaden zufügt, erhöht sich seine Frequenz.\nVerkaufspreis:" }
entries[169314] = { ["name"] = "Azsharas Born der Macht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 10.\nBenutzen: Kanalisiert bis zu 4 Sek. lang latente Magie, was Euren Primärwert um 30 erhöht. Für jede Sekunde, die Ihr kanalisiert, wird die Dauer verlängert, bis zu maximal 30 Sek. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[169315] = { ["name"] = "Erlasse der Ungläubigen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nAnlegen: Ihr erhaltet alle 40 Sek. einen Schild, der [ 262 * (1 + Vielseitigkeit)] körperlichen Schaden absorbiert. Wenn der Schild aufgebraucht wird, erhaltet Ihr Fanatismus. Dadurch absorbieren weitere Schilde 10% mehr Schaden, bis zu maximal 100%.\nBenutzen: Verkündet 'Edikt der Meereshexe'. Dadurch absorbiert diese Fähigkeit stattdessen Magieschaden. Setzt außerdem Fanatismus zurück. (40 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[169316] = { ["name"] = "Aufgeschobenes Urteil", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nAnlegen: Schiebt alle 3 Sek. [ 7 * (1 + Vielseitigkeit)] Heilung auf. Bewegung setzt die aufgeschobene Heilung frei und heilt Eure 3 am schwersten verletzten Verbündeten.\nVerkaufspreis:" }
entries[169317] = { ["name"] = "Bindungsstein des Bezauberers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 10 Vielseitigkeit\nAnlegen: Eure Fähigkeiten haben eine Chance, Euren Primärwert 30 Sek. lang um 15 zu erhöhen.\nVerkaufspreis:" }
entries[169318] = { ["name"] = "Schockbeißers Reißzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhöht Euer Tempo 30 Sek. lang um 23 . (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[169319] = { ["name"] = "Tröpfelnde Tintenkapsel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nAnlegen: Eure Schadensfähigkeiten haben bei Gegnern mit mehr als 30% Gesundheit eine sehr hohe Chance, sie mit 'Leitfähige Tinte' zu belegen. Wenn die Gesundheit des Gegners unter 30% fällt, verursacht 'Leitfähige Tinte' [ 26 * (1 + Vielseitigkeit)] Naturschaden pro Stapel.\nVerkaufspreis:" }
entries[169320] = { ["name"] = "Beschädigter Energiekern", ["text"] = "Questgegenstand" }
entries[169321] = { ["name"] = "Hochgeborenenkompendium der Zerschlagung", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke]\nAnlegen: Eure Angriffe haben eine Chance, den Gegner mit 'Vulkanischer Druck' zu belegen, wodurch er 10 Sek. lang alle 2 Sek. 3 Feuerschaden erleidet. Wenn 'Vulkanischer Druck' 6 Stapel erreicht, fügt eine Eruption allen Gegnern in der Nähe 44 Feuerschaden zu.\nVerkaufspreis:" }
entries[169322] = { ["name"] = "Bündel des abenteuerlustigen Hopflings", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen abenteuerlustigen Hopfling beschwört.\nMit Rechtsklick Euren abenteuerlustigen Hopfling beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[169325] = { ["name"] = "Versteinerte kohlschwarze Schuppe", ["text"] = "Questgegenstand\nBenutzen: Verleiht Eurem Herz von Azeroth die Macht einer versteinerten kohlschwarzen Schuppe.\n\"Diese uralte Schuppe verkörpert die Erde und wurde in kohlschwarzem Feuer gehärtet.\"" }
entries[169326] = { ["name"] = "Abyssalsplitter", ["text"] = "Questgegenstand\n\"Diese Splitter enthalten gewaltige Macht und befinden sich meist im Besitz der mächtigsten Wesen in Nazjatar.\"" }
entries[169328] = { ["name"] = "Hochgeborenenkompendium der Stürme", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, einen Taifun zu erschaffen, der sich in Richtung von Gegnern bewegt. Der Taifun verursacht 16 Naturschaden und gewährt Euch 15 Sek. lang 4 Tempo, bis zu maximal ( 4 * 4) Tempo.\nVerkaufspreis:" }
entries[169329] = { ["name"] = "Ewiges Ornament", ["text"] = "Wird beim Aufheben gebunden" }
entries[169331] = { ["name"] = "Mardivas' Arkankasten", ["text"] = "Questgegenstand\nEinzigartig\nMunition\nZahnradsockel\nZahnradsockel\n\"Ein aufwendiger, vom wahnsinnigen Magier Mardivas erschaffener Behälter. An den Seiten des Geräts sind zwei Löcher sichtbar.\"" }
