entries[169486] = { ["name"] = "Tuch der Shirakess", ["text"] = "Benthisch\nWird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 4.\nAnlegen: Verringert den erlittenen Frostschaden in Nazjatar und im Ewigen Palast um 3%.\nVerkaufspreis:" }
entries[169487] = { ["name"] = "Tiefenpirscherumhang", ["text"] = "Benthisch\nWird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nAnlegen: Ihr habt eine Chance, zufällige Fische von Kreaturen in Nazjatar und im Ewigen Palast zu erbeuten.\nVerkaufspreis:" }
entries[169488] = { ["name"] = "Großumhang der Zanj'ir", ["text"] = "Benthisch\nWird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\n+ 3 Vielseitigkeit\nAnlegen: Erhöht Eure Gesundheit, nachdem Ihr in Nazjatar und im Ewigen Palast wiederbelebt werdet, um 30%.\nVerkaufspreis:" }
entries[169489] = { ["name"] = "Sturmwogercape der Azsh'ari", ["text"] = "Benthisch\nWird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nAnlegen: Ihr habt Zugriff auf die besonderen Vorräte der Murlochändler.\nVerkaufspreis:" }
entries[169490] = { ["name"] = "Relikt des Schwarzen Imperiums", ["text"] = "Benutzen: Entfernt einen Stapel von N'Zoths Schutz von einem Gegner.\n\"Ein geheimnisvolles und mächtiges Objekt, das Diener von N'Zoth bei sich tragen.\"" }
entries[169491] = { ["name"] = "Fokussierte Lebensanima", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: [ [ Kombiniert 3 fokussierte Lebensanima, um [den Fetisch der Dunkelhöhlen][die Pralle Saat des Lebens] zu erschaffen, womit das Herz von Azeroth mit ['Anima von Leben und Tod']['Invokation der Lebensbinderin'] verstärkt werden kann. Der erschaffene Gegenstand hängt von Eurer Beutespezialisierung ab. ] ]" }
entries[169492] = { ["name"] = "Rezept: Trank der umzingelten Stärke", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Trank der umzingelten Stärke effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nBenötigt Ankoaner der Meeresklinge\n- Respektvoll\nVerkaufspreis:\nTrank der umzingelten Stärke\nBenutzen: Ermächtigt Eure Fähigkeiten und erhöht Eure Hauptwert 25 Sek. lang um 108 . Euer Primärwert erhöht sich zusätzlich um die Zahl der Gegner innerhalb von 8 Metern von Euch, bis zu einem Maximum von ( 108 * 5). (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Winterkuss (3), Kristallphiole" }
entries[169493] = { ["name"] = "Rezept: Trank der Rekonstitution", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Trank der Rekonstitution effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nBenötigt Ankoaner der Meeresklinge\n- Respektvoll\nVerkaufspreis:\nTrank der Rekonstitution\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 816 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Akundas Biss (3), Kristallphiole" }
entries[169494] = { ["name"] = "Rezept: Trank der festen Entschlossenheit", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Trank der festen Entschlossenheit effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nBenötigt Ankoaner der Meeresklinge\n- Respektvoll\nVerkaufspreis:\nTrank der festen Entschlossenheit\nBenutzen: Konzentriert Euren Blick auf einen einzelnen Gegner. Eure Schaden verursachenden Fähigkeiten markieren das Ziel und erhöhen Eure Chance auf kritische Treffer gegen dieses Ziel um bis zu 20%. Wenn Ihr einem neuen Ziel Schaden zufügt, wird Euer Fokus zurückgesetzt. Hält 25 Sek. lang an. Funktioniert nicht bei Zielen über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Winterkuss (3), Kristallphiole" }
entries[169495] = { ["name"] = "Rezept: Überlegener Kampftrank der Beweglichkeit", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen überlegenen Kampftrank der Beweglichkeit effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(175)\nVerkaufspreis:\nÜberlegener Kampftrank der Beweglichkeit\nBenutzen: Erhöht Eure Beweglichkeit 25 Sek. lang um 363 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Flussknospe (3), Kristallphiole" }
