entries[169504] = { ["name"] = "Rezept: Großer mystischer Kessel", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen großen mystischen Kessel effizienter herstellt.\nChance auf die Herstellung mehrerer Kessel.\nBenötigt Alchemie von Kul Tiras\n(175)\nBenötigt Ankoaner der Meeresklinge\n- Ehrfürchtig\nVerkaufspreis:\nGroßer mystischer Kessel\nWird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:\nBenötigt Großes Fläschchen der Ströme (3), Großes Fläschchen der unendlichen Tiefe (3), Großes Fläschchen des weiten Horizonts (3), Großes Fläschchen des Tiefensogs (3), Expulsom (4)" }
entries[169505] = { ["name"] = "Pläne: Plattenstulpen des berüchtigten Kämpfers", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Plattenstulpen des berüchtigten Kämpfers effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung von Plattenstulpen des berüchtigten Kämpfers.\nBenötigt Schmiedekunst von Kul Tiras (160)\nVerkaufspreis:\nAllianz\nPlattenstulpen des berüchtigten Kämpfers\nWird beim Anlegen gebunden\nHände Platte\n12 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 55 / 55\nVerkaufspreis:\nHorde\nPlattenstulpen des berüchtigten Kämpfers\nWird beim Anlegen gebunden\nHände Platte\n12 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 55 / 55\nVerkaufspreis:\nBenötigt Osmeniterz (14), Sturmsilbererz (4), Langlebiger Fluxus (8), Expulsom (2)\nOptionale Reagenzien: [] (#50)" }
