entries[169586] = { ["name"] = "Muster: Satinumhang des berüchtigten Kämpfers", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Satinumhang des berüchtigten Kämpfers effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Satinumhangs des berüchtigten Kämpfers.\nBenötigt Schneiderei von Kul Tiras (160)\nVerkaufspreis:\nAllianz\nSatinumhang des berüchtigten Kämpfers\nWird beim Anlegen gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+5 Ausdauer\nVerkaufspreis:\nHorde\nSatinumhang des berüchtigten Kämpfers\nWird beim Anlegen gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+5 Ausdauer\nVerkaufspreis:\nBenötigt Vergoldetes Seetuch (18), Tiefseesatin (6), Nylonfaden (23), Expulsom (2)\nOptionale Reagenzien: [] (#50)" }
entries[169587] = { ["name"] = "Muster: Satinumhang des berüchtigten Kämpfers", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Satinumhang des berüchtigten Kämpfers effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Satinumhangs des berüchtigten Kämpfers.\nBenötigt Schneiderei von Kul Tiras (170)\nVerkaufspreis:\nAllianz\nSatinumhang des berüchtigten Kämpfers\nWird beim Anlegen gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+5 Ausdauer\nVerkaufspreis:\nHorde\nSatinumhang des berüchtigten Kämpfers\nWird beim Anlegen gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+5 Ausdauer\nVerkaufspreis:\nBenötigt Vergoldetes Seetuch (15), Tiefseesatin (5), Nylonfaden (20), Expulsom\nOptionale Reagenzien: [] (#50)" }
entries[169588] = { ["name"] = "Schulterschutz der zersplitterten Realität", ["text"] = "Wird beim Aufheben gebunden\nSchulter Kette\n10 Rüstung\n+10 [Beweglichkeit oder Intelligenz]\n+11 Ausdauer\nHaltbarkeit 100 / 100\n\nAktive Azeritische Kräfte (0/5):\n- Eine neue Macht ist verfügbar. - Eine neue Macht ist verfügbar. - Eine neue Macht ist verfügbar. - Eine neue Macht ist verfügbar. - Azeritverstärkt ist verfügbar.\nVerkaufspreis:" }
