entries[169591] = { ["name"] = "Rissiger Datenzylinder", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein beschädigtes Fragment von Norgannons Daten.\"" }
entries[169593] = { ["name"] = "Großes Speicherfragment", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine große Menge Daten von Norgannon.\"" }
entries[169594] = { ["name"] = "Rostbedeckte Scheibe", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Von Rost bedeckt, aber immer noch funktionsfähig.\"" }
entries[169595] = { ["name"] = "Versengte Datenscheibe", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Von Hitze beschädigte Daten von Norgannon.\"" }
entries[169596] = { ["name"] = "Zin'anthidententakel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Selbst nachdem es von der Pflanze getrennt wurde, hält sich dieses Tentakel immer noch fest geschlossen.\"" }
entries[169597] = { ["name"] = "Osmenitsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Einige kleine, nicht verwertbare Splitter Osmenit.\"" }
entries[169598] = { ["name"] = "Osmenitstaub", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Selbst als Erzstaub glänzt Osmenit immer noch herrlich.\"" }
entries[169599] = { ["name"] = "Championmarke des Mampfkampfs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Braufest\n\"Tauscht fünf davon ein, um die Mampfkampftrophäe des Braufests zu erhalten.\"" }
entries[169600] = { ["name"] = "Rezept: Trank der umzingelten Stärke", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Trank der umzingelten Stärke effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nBenötigt Die Entfesselten\n- Respektvoll\nVerkaufspreis:\nTrank der umzingelten Stärke\nBenutzen: Ermächtigt Eure Fähigkeiten und erhöht Eure Hauptwert 25 Sek. lang um 108 . Euer Primärwert erhöht sich zusätzlich um die Zahl der Gegner innerhalb von 8 Metern von Euch, bis zu einem Maximum von ( 108 * 5). (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Winterkuss (3), Kristallphiole" }
entries[169601] = { ["name"] = "Rezept: Trank der Rekonstitution", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Trank der Rekonstitution effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nBenötigt Die Entfesselten\n- Respektvoll\nVerkaufspreis:\nTrank der Rekonstitution\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 816 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Akundas Biss (3), Kristallphiole" }
entries[169602] = { ["name"] = "Rezept: Trank der festen Entschlossenheit", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Trank der festen Entschlossenheit effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nBenötigt Die Entfesselten\n- Respektvoll\nVerkaufspreis:\nTrank der festen Entschlossenheit\nBenutzen: Konzentriert Euren Blick auf einen einzelnen Gegner. Eure Schaden verursachenden Fähigkeiten markieren das Ziel und erhöhen Eure Chance auf kritische Treffer gegen dieses Ziel um bis zu 20%. Wenn Ihr einem neuen Ziel Schaden zufügt, wird Euer Fokus zurückgesetzt. Hält 25 Sek. lang an. Funktioniert nicht bei Zielen über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (8), Winterkuss (3), Kristallphiole" }
entries[169603] = { ["name"] = "Rezept: Großer mystischer Kessel", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen großen mystischen Kessel effizienter herstellt.\nChance auf die Herstellung mehrerer Kessel.\nBenötigt Alchemie von Kul Tiras\n(175)\nBenötigt Die Entfesselten\n- Ehrfürchtig\nVerkaufspreis:\nGroßer mystischer Kessel\nWird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:\nBenötigt Großes Fläschchen der Ströme (3), Großes Fläschchen der unendlichen Tiefe (3), Großes Fläschchen des weiten Horizonts (3), Großes Fläschchen des Tiefensogs (3), Expulsom (4)" }
entries[169604] = { ["name"] = "Formel: Bündnis des kritischen Trefferwerts", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Bündnis des kritischen Trefferwerts' effizienter herstellt.\nEinen Ring dauerhaft verzaubern, sodass der kritische Trefferwert um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (170)\nBenötigt Die Entfesselten\n- Respektvoll\nVerkaufspreis:" }
entries[169605] = { ["name"] = "Formel: Bündnis des Tempos", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Bündnis des Tempos' effizienter herstellt.\nEinen Ring dauerhaft verzaubern, sodass das Tempo um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (170)\nBenötigt Die Entfesselten\n- Respektvoll\nVerkaufspreis:" }
entries[169606] = { ["name"] = "Formel: Bündnis der Meisterschaft", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Bündnis der Meisterschaft' effizienter herstellt.\nEinen Ring dauerhaft verzaubern, sodass die Meisterschaft um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (175)\nBenötigt Die Entfesselten\n- Respektvoll\nVerkaufspreis:" }
entries[169607] = { ["name"] = "Formel: Bündnis der Vielseitigkeit", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Bündnis der Vielseitigkeit' effizienter herstellt.\nEinen Ring dauerhaft verzaubern, sodass die Vielseitigkeit um 28 erhöht wird. Materialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (175)\nBenötigt Die Entfesselten\n- Respektvoll\nVerkaufspreis:" }
entries[169608] = { ["name"] = "Reißende Sägezahnklinge", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n7 - 13 Schaden Geschwindigkeit 2.60\n(3.8 Schaden pro Sekunde)\n+4 Stärke\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[169609] = { ["name"] = "Bauplan: Motor mit Turbolader", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Motor mit Turbolader herstellt.\nStellt einen Motor mit Turbolader her.\nBenötigt Ingenieurskunst von Kul Tiras (160)\nMotor mit Turbolader\nBenutzen: Kombiniert ein monelitverstärktes Chassis und einen Motor mit Turbolader, um ein Xiwyllag-Flugfahrboot herzustellen. Das ist ein sehr schnelles Reittier.\nBenötigt Moneliterz (100), Sturmsilbererz (50), Isoliertes Kabel (25), Chemische Sprengkapsel (12), Expulsom (8)" }
entries[169610] = { ["name"] = "Kiste mit E.R.S.A.T.Z.-Teilen", ["text"] = "Mechagontüfteleien\nWird beim Aufheben gebunden\nBenutzen: Entpackt eine Kiste mit E.R.S.A.T.Z.-Teilen, um an den Inhalt zu gelangen.\nHandwerksmaterial\n\"250 Ersatzteile, die ordentlich angeordnet sind.\"\nVerkaufspreis:" }
entries[169611] = { ["name"] = "Kräuterkundetechnik: Zin'anthide", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Zin'anthiden effizienter sammelt.\nSammelt Zin'anthiden effektiver.\nBenötigt Kräuterkunde von Kul Tiras (155)\nVerkaufspreis:" }
entries[169612] = { ["name"] = "Abbauverfahren: Osmenitvorkommen", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Osmenitvorkommen effizienter abbaut.\nSammelt Osmeniterz noch effektiver.\nBenötigt Bergbau von Kul Tiras (155)\nVerkaufspreis:" }
entries[169613] = { ["name"] = "Abbauverfahren: Osmenitflöz", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Osmenitflöze effizienter abbaut.\nBaut Osmenitflöze noch effektiver ab.\nBenötigt Bergbau von Kul Tiras (155)\nVerkaufspreis:" }
entries[169614] = { ["name"] = "Auszeichnung des Rufs zu den Waffen", ["text"] = "Rang 3\nWird beim Aufheben gebunden\n\"Verliehen für den erfolgreichen Abschluss von 'Ruf zu den Waffen'-Quests.\"" }
entries[169615] = { ["name"] = "Kleiner Schädel", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein kleiner Schädel, der in einem Schleim gefunden wurde.\"" }
